    ret = gpiod_line_request_output(line, "gpio-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d on %s set as output. Starting %d cycles.\n",
           GPIO_LINE_OFFSET, GPIO_CHIP_NAME, NUM_CYCLES);

    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        int val = (i % 2) ? 1 : 0;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        printf("Cycle %d: GPIO %d set to %d\n", i + 1, GPIO_LINE_OFFSET, val);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < CYCLE_DELAY_SEC && keep_running; s++) {
            sleep(1);
        }
    }

    /* Clean up: set line low and release resources */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
