#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_SINGLE_0 (0x4 << 12)
#define ADS1115_CONFIG_PGA_4_096V (0x1 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (1 << 8)
#define ADS1115_CONFIG_DR_128SPS (0x4 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x3 << 0)

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF)};
    if (write(fd, buf, 3) != 3) {
        perror("i2c_write_reg16: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg16: write reg failed");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("i2c_read_reg16: read failed");
        return -1;
    }
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_SINGLE_0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) < 0) {
        goto cleanup;
    }

    usleep(10000);

    uint16_t raw;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &raw) < 0) {
        goto cleanup;
    }

    int16_t signed_raw = (int16_t)raw;
    float voltage = (signed_raw * 4.096) / 32768.0;
    printf("Voltage: %.4f V\n", voltage);

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

