        printf("GPIO %d = %d, GPIO %d = %d\n", GPIO_PIN_1, val1, GPIO_PIN_2, val2);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    /* Clean up: set lines low and release resources */
    gpiod_line_set_value(line1, 0);
    gpiod_line_set_value(line2, 0);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
