#define CMD_READ_TEMP 0xE0
#define CMD_READ_HUMIDITY 0xE5
#define CMD_READ_ID_1 0xFA
#define CMD_READ_ID_2 0x0F
#define CMD_RESET 0xFE
#define CMD_WRITE_USER_REG 0xE6
#define CMD_READ_USER_REG 0xE7
#define CMD_READ_PREV_TEMP 0xE1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (expected %zu, got %zd): %s\n", len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int si7021_reset(int fd) {
    if (i2c_write_byte(fd, CMD_RESET) < 0) return -1;
    usleep(15000);
    return 0;
}

static int si7021_read_id(int fd, uint8_t *id) {
    if (i2c_write_byte(fd, CMD_READ_ID_1) < 0) return -1;
    usleep(10000);
    if (i2c_read_bytes(fd, id, 8) < 0) return -1;
    return 0;
}

static int si7021_read_temp(int fd, float *temp) {
    if (i2c_write_byte(fd, CMD_MEASURE_TEMP_HOLD) < 0) return -1;
    usleep(10000);
    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp = (175.72f * raw / 65536.0f) - 46.85f;
    return 0;
}

static int si7021_read_humidity(int fd, float *hum) {
    if (i2c_write_byte(fd, CMD_MEASURE_TEMP_HOLD) < 0) return -1;
    usleep(10000);
    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    float t = (175.72f * raw / 65536.0f) - 46.85f;
    *hum = (125.0f * raw / 65536.0f) - 6.0f;
    if (*hum < 0.0f) *hum = 0.0f;
    if (*hum > 100.0f) *hum = 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (si7021_reset(fd) < 0) {
        fprintf(stderr, "Sensor reset failed.\n");
        close(fd);
        return 1;
    }

    uint8_t id[8];
    if (si7021_read_id(fd, id) < 0) {
        fprintf(stderr, "Failed to read sensor ID.\n");
        close(fd);
        return 1;
    }

    printf("SI7021 detected. ID: ");
    for (int i = 0; i < 8; i++) printf("%02X", id[i]);
    printf("\n");

    while (running) {
        float temp, hum;
        if (si7021_read_temp(fd, &temp) < 0) {
            fprintf(stderr, "Temperature read failed.\n");
        } else if (si7021_read_humidity(fd, &hum) < 0) {
            fprintf(stderr, "Humidity read failed.\n");
        } else {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        }
        sleep(5);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define ADS1115_ADDR 0x48
#define I2C_BUS "/dev/i2c-1"

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_AIN0_GND (0x4 << 12)
#define ADS1115_CONFIG_PGA_4_096V (0x1 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (1 << 8)
#define ADS1115_CONFIG_DR_128SPS (0x4 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x3 << 0)

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF)};
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_read(int fd, int16_t *out) {
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) < 0) return -1;

    for (int i = 0; i < 10; i++) {
        uint16_t cfg;
        if (i2c_read_reg16(fd, ADS1115_REG_CONFIG, &cfg) < 0) return -1;
        if (cfg & ADS1115_CONFIG_OS_BEGIN) break;
        usleep(10000);
        if (i == 9) return -1;
    }

    uint16_t raw;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &raw) < 0) return -1;
    *out = (int16_t)raw;
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(fd);
        return 1;
    }

    printf("Sampling ADS1115 at 0x%02X on %s...\n", ADS1115_ADDR, I2C_BUS);

    for (int i = 0; i < 3 && running; i++) {
        int16_t raw;
        if (ads1115_read(fd, &raw) < 0) {
            fprintf(stderr, "Error reading ADC (attempt %d)\n", i + 1);
            close(fd);
            return 1;
        }
        printf("Reading %d: %d\n", i + 1, raw);
        sleep(1);
    }

    close(fd);
    printf("Program finished.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 6
#define CYCLES 256

static const unsigned int pins[NUM_PINS] = {8, 9, 10, 11, 23, 24};

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int i;

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
        values[i] = 0;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "gpio-output", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < CYCLES && running; i++) {
        for (int j = 0; j < NUM_PINS; j++) {
            values[j] = (i >> j) & 1;
            if (gpiod_line_set_value(lines[j], values[j]) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for pin %u\n", pins[j]);
                goto cleanup;
            }
            printf("Pin %u: %d\n", pins[j], values[j]);
        }
        usleep(100000);
    }

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 8

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line, "gpio-output", 1) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d set to HIGH\n", GPIO_LINE);
    fflush(stdout);

    cleanup_and_exit(0);
    return 0;
}

