#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27
#define DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL, *line18 = NULL, *line27 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line17 || !line18 || !line27) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line17, "gpio-out", 0) < 0 ||
        gpiod_line_request_output(line18, "gpio-out", 0) < 0 ||
        gpiod_line_request_output(line27, "gpio-out", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        int val = 0;
        if (gpiod_line_set_value(line17, val) < 0 ||
            gpiod_line_set_value(line18, val) < 0 ||
            gpiod_line_set_value(line27, val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("GPIO 17=0, GPIO 18=0, GPIO 27=0\n");
        usleep(DELAY_US);

        val = 1;
        if (gpiod_line_set_value(line17, val) < 0 ||
            gpiod_line_set_value(line18, val) < 0 ||
            gpiod_line_set_value(line27, val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("GPIO 17=1, GPIO 18=1, GPIO 27=1\n");
        usleep(DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (line27) gpiod_line_release(line27);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

