#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define POLL_INTERVAL_US 500000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two GPIO lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (line1 == NULL) {
        perror("gpiod_chip_get_line(GPIO_PIN_1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (line2 == NULL) {
        perror("gpiod_chip_get_line(GPIO_PIN_2)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    ret = gpiod_line_request_output(line1, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line2, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    printf("GPIO output on GPIO %d and GPIO %d. Press Ctrl+C to exit.\n",
           GPIO_PIN_1, GPIO_PIN_2);

    /* Main loop: toggle the two lines every 0.5 seconds */
    while (program_running) {
        ret = gpiod_line_set_value(line1, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(line1, 1)");
            break;
        }
        printf("GPIO %d HIGH\n", GPIO_PIN_1);

        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(line2, 0)");
            break;
        }
        printf("GPIO %d LOW\n", GPIO_PIN_2);

        usleep(POLL_INTERVAL_US);

        if (!program_running) {
            break;
        }

        ret = gpiod_line_set_value(line1, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(line1, 0)");
            break;
        }
        printf("GPIO %d LOW\n", GPIO_PIN_1);

        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(line2, 1)");
            break;
        }
        printf("GPIO %d HIGH\n", GPIO_PIN_2);

        usleep(POLL_INTERVAL_US);
    }

cleanup:
    /* Ensure lines are left low before releasing */
    if (line1 != NULL) {
        gpiod_line_set_value(line1, 0);
        gpiod_line_release(line1);
    }
    if (line2 != NULL) {
        gpiod_line_set_value(line2, 0);
        gpiod_line_release(line2);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("\nGPIO output released. Exiting.\n");
    return EXIT_SUCCESS;
}

