#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CONSUMER "gpio-output"
#define NUM_PINS 4

static const unsigned int pins[NUM_PINS] = {8, 9, 10, 11};

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get each line and request it as output, initially low */
    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u\n", pins[i]);
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u\n", pins[i]);
            goto cleanup;
        }
    }

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        goto cleanup;
    }

    /* Main loop: toggle each line every 0.1 seconds */
    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                perror("gpiod_line_get_value");
                goto cleanup;
            }
            val = !val;
            if (gpiod_line_set_value(lines[i], val) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup;
            }
            printf("Pin %u: %s\n", pins[i], val ? "HIGH" : "LOW");
        }
        fflush(stdout);
        usleep(100000); /* 0.1 seconds */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure all lines are low before releasing */
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

