#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CONSUMER    "hcsr04"
#define TIMEOUT_US  30000   /* 30 ms timeout for echo */
#define SOUND_SPEED 0.0343 /* cm/us at 20 C */

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

static long long now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static int wait_for_level(struct gpiod_line *line, int target, long long deadline_us)
{
    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            return -1;
        }
        if (val == target)
            return 0;
        if (now_us() > deadline_us)
            return -1; /* timeout */
    }
    return -1;
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(0)");
        return -1;
    }
    usleep(2);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value(1)");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(0)");
        return -1;
    }

    /* Wait for echo rising edge */
    if (wait_for_level(echo, 1, now_us() + TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo rising edge\n");
        return -1;
    }

    long long start = now_us();

    /* Wait for echo falling edge */
    if (wait_for_level(echo, 0, start + TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo falling edge\n");
        return -1;
    }

    long long end = now_us();
    long long diff = end - start;

    /* distance = (time * speed) / 2 */
    double distance = (double)diff * SOUND_SPEED / 2.0;

    if (distance < 2.0 || distance > 400.0) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1;
    }

    return (int)(distance + 0.5);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = measure_distance(trig, echo);
        if (distance >= 0) {
            printf("Distance: %d cm\n", distance);
        } else {
            fprintf(stderr, "Measurement failed\n");
        }
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig)
        gpiod_line_release(trig);
    if (echo)
        gpiod_line_release(echo);
    if (chip)
        gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return ret;
}

