        printf("Cycle %d: GPIO 2 and 3 HIGH\n", i + 1);
        fflush(stdout);

        /* Wait 1 second */
        sleep(1);

        /* Set both lines low */
        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value (pin 2 low)");
            goto cleanup;
        }
