#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT11_PIN 4
#define MAX_RETRIES 5
#define TIMEOUT_US 1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int target, int timeout_us) {
    int elapsed = 0;
    while (gpiod_line_get_value(line) != target) {
        if (!running) return -1;
        usleep(1);
        elapsed++;
        if (elapsed >= timeout_us) return -1;
    }
    return elapsed;
}

static int read_dht11(struct gpiod_line *line, float *temperature, float *humidity) {
    uint8_t data[5] = {0};
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (!running) return -1;

        // Send start signal
        if (gpiod_line_request_output(line, "dht11", 0) < 0) return -1;
        gpiod_line_set_value(line, 0);
        usleep(18000); // 18ms low
        gpiod_line_set_value(line, 1);
        usleep(30);    // 30us high

        // Switch to input
        if (gpiod_line_request_input(line, "dht11") < 0) return -1;

        // Wait for sensor response (low then high)
        if (wait_for_level(line, 0, TIMEOUT_US) < 0) { retries++; continue; }
        if (wait_for_level(line, 1, TIMEOUT_US) < 0) { retries++; continue; }

        // Read 40 bits
        for (int i = 0; i < 40; i++) {
            if (wait_for_level(line, 0, TIMEOUT_US) < 0) { retries++; continue; }

            int high_us = wait_for_level(line, 1, TIMEOUT_US);
            if (high_us < 0) { retries++; continue; }

            data[i / 8] <<= 1;
            if (high_us > 50) {
                data[i / 8] |= 1;
            }
        }

        // Checksum
        uint8_t checksum = data[0] + data[1] + data[2] + data[3];
        if (checksum != data[4]) {
            fprintf(stderr, "Checksum error: expected 0x%02X, got 0x%02X\n", checksum, data[4]);
            retries++;
            continue;
        }

        *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
        *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
        if (data[2] & 0x80) {
            *temperature = -*temperature;
        }

        return 0;
    }

    fprintf(stderr, "DHT11 read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temperature, humidity;
    int ret = 1;

    // Setup signal handler for clean exit
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        goto cleanup;
    }

    // Read DHT11
    if (read_dht11(line, &temperature, &humidity) == 0) {
        printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
        ret = 0;
    } else {
        fprintf(stderr, "Failed to read DHT11 sensor\n");
    }

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

