#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define NUM_CYCLES 3
#define CYCLE_DELAY_SEC 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_output(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static int read_input(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        perror("gpiod_line_get_value");
        return -1;
    }
    return val;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line(pin1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line(pin2)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output(pin1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output(pin2)");
        goto cleanup;
    }

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        int val1 = read_input(line1);
        int val2 = read_input(line2);

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "Error reading GPIO values\n");
            goto cleanup;
        }

        if (val1 < 0 || val1 > 1 || val2 < 0 || val2 > 1) {
            fprintf(stderr, "Invalid GPIO value: pin1=%d, pin2=%d\n", val1, val2);
            goto cleanup;
        }

        if (set_output(line1, val1) < 0 || set_output(line2, val2) < 0) {
            fprintf(stderr, "Error setting GPIO values\n");
            goto cleanup;
        }

        printf("Cycle %d: GPIO %d = %d, GPIO %d = %d\n", i + 1, GPIO_PIN_1, val1, GPIO_PIN_2, val2);

        for (int s = 0; s < CYCLE_DELAY_SEC && running; s++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

