#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18
#define PWM_FREQ 1000
#define PWM_RANGE 255
#define DELAY_US 150000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler.\n");
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioPWM(PWM_PIN_1, 128) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", PWM_PIN_1);
            break;
        }
        if (gpioPWM(PWM_PIN_2, 128) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", PWM_PIN_2);
            break;
        }
        if (gpioPWM(PWM_PIN_3, 128) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", PWM_PIN_3);
            break;
        }
        printf("PWM on GPIO %d, %d, %d: 128/255\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);
        fflush(stdout);

        gpioDelay(DELAY_US);

        if (gpioPWM(PWM_PIN_1, 0) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", PWM_PIN_1);
            break;
        }
        if (gpioPWM(PWM_PIN_2, 0) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", PWM_PIN_2);
            break;
        }
        if (gpioPWM(PWM_PIN_3, 0) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", PWM_PIN_3);
            break;
        }
        printf("PWM on GPIO %d, %d, %d: 0/255\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);
        fflush(stdout);

        gpioDelay(DELAY_US);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    printf("\nPWM stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 18
#define NUM_CYCLES 3
#define DELAY_MS 100

static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Register signal handler for clean exit */
    signal(SIGINT, handle_sigint);

    /* Open GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request line as output, initially low */
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: apply high, then low */
    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Failed to set GPIO high");
            goto cleanup;
        }
        printf("GPIO %d set HIGH\n", GPIO_LINE);
        fflush(stdout);

        usleep(DELAY_MS * 1000);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Failed to set GPIO low");
            goto cleanup;
        }
        printf("GPIO %d set LOW\n", GPIO_LINE);
        fflush(stdout);

        usleep(DELAY_MS * 1000);
    }

cleanup:
    /* Ensure line is low on exit */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

