#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define OPT3001_ADDR 0x44
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    int fd;
    uint8_t reg;
    uint8_t buf[2];
    int16_t raw;
    float lux;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(fd);
        return 1;
    }

    // Read result register (0x00)
    reg = 0x00;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        close(fd);
        return 1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read result register");
        close(fd);
        return 1;
    }

    raw = (buf[0] << 8) | buf[1];
    raw = raw >> 4; // Remove the exponent bits
    lux = raw * 0.01f;

    printf("Lux: %.2f\n", lux);

    close(fd);
    return 0;
}

