#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B115200
#define READ_TIMEOUT_SEC 1
#define READ_TIMEOUT_USEC 0

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int init_serial(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_iflag &= ~IGNBRK;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_serial(int fd, char *buf, size_t len) {
    fd_set rfds;
    struct timeval tv;

    FD_ZERO(&rfds);
    FD_SET(fd, &rfds);

    tv.tv_sec = READ_TIMEOUT_SEC;
    tv.tv_usec = READ_TIMEOUT_USEC;

    int retval = select(fd + 1, &rfds, NULL, NULL, &tv);
    if (retval < 0) {
        if (errno == EINTR) return 0;
        fprintf(stderr, "select() error: %s\n", strerror(errno));
        return -1;
    }
    if (retval == 0) {
        fprintf(stderr, "Timeout: no data from device\n");
        return -1;
    }

    ssize_t n = read(fd, buf, len - 1);
    if (n < 0) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) return 0;
        fprintf(stderr, "read() error: %s\n", strerror(errno));
        return -1;
    }
    if (n == 0) {
        fprintf(stderr, "Device closed unexpectedly\n");
        return -1;
    }

    buf[n] = '\0';
    return (int)n;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = init_serial(SERIAL_PORT);
    if (fd < 0) {
        return 1;
    }

    char buffer[256];
    int bytes_read;

    while (keep_running) {
        bytes_read = read_serial(fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("Received: %s", buffer);
            fflush(stdout);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from serial port\n");
            break;
        }
    }

    if (close(fd) != 0) {
        fprintf(stderr, "Error closing serial port: %s\n", strerror(errno));
        return 1;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN_1 4
#define GPIO_PIN_2 17
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 4)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 17)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (pin 4)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (pin 17)");
        goto cleanup;
    }

    /* Main loop: toggle both lines every 10 ms */
    while (running) {
        int val1 = gpiod_line_get_value(line1);
        if (val1 < 0) {
            perror("gpiod_line_get_value (pin 4)");
            goto cleanup;
        }

        int val2 = gpiod_line_get_value(line2);
        if (val2 < 0) {
            perror("gpiod_line_get_value (pin 17)");
            goto cleanup;
        }

        if (gpiod_line_set_value(line1, !val1) < 0) {
            perror("gpiod_line_set_value (pin 4)");
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, !val2) < 0) {
            perror("gpiod_line_set_value (pin 17)");
            goto cleanup;
        }

        printf("GPIO 4: %d, GPIO 17: %d\n", !val1, !val2);
        fflush(stdout);

        usleep(10000); /* 10 ms */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

