        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, "gpio2-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d initialized as output. Starting %d cycles every %d seconds.\n",
           GPIO_LINE_OFFSET, NUM_CYCLES, CYCLE_DURATION_SEC);

    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        int value = (i % 2) ? 1 : 0;

        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("Cycle %d: GPIO %d set to %d\n", i + 1, GPIO_LINE_OFFSET, value);
        fflush(stdout);

        /* Sleep for the cycle duration, checking for signal every second */
        for (int s = 0; s < CYCLE_DURATION_SEC && keep_running; s++) {
            sleep(1);
        }
    }

    /* Clean up: set line low and release */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d released. Exiting.\n", GPIO_LINE_OFFSET);
    return EXIT_SUCCESS;
}

