#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define POLL_INTERVAL_US 100000  /* 0.1 seconds */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (line1 == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_PIN_1, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (line2 == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_PIN_2, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initially low */
    ret = gpiod_line_request_output(line1, "gpio-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_PIN_1, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line2, "gpio-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_PIN_2, strerror(errno));
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO output on GPIO %d and GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN_1, GPIO_PIN_2);

    /* Main loop: toggle the two lines every 0.1 seconds */
    while (program_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "Error reading GPIO lines: %s\n", strerror(errno));
            break;
        }

        /* Toggle the lines */
        val1 = !val1;
        val2 = !val2;

        ret = gpiod_line_set_value(line1, val1);
        if (ret < 0) {
            fprintf(stderr, "Error writing to GPIO line %d: %s\n", GPIO_PIN_1, strerror(errno));
            break;
        }

        ret = gpiod_line_set_value(line2, val2);
        if (ret < 0) {
            fprintf(stderr, "Error writing to GPIO line %d: %s\n", GPIO_PIN_2, strerror(errno));
            break;
        }

        printf("GPIO %d = %d, GPIO %d = %d\n", GPIO_PIN_1, val1, GPIO_PIN_2, val2);

        usleep(POLL_INTERVAL_US);
    }

    /* Clean up: set lines low and release resources */
    gpiod_line_set_value(line1, 0);
    gpiod_line_set_value(line2, 0);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    printf("\nGPIO output released. Exiting.\n");
    return EXIT_SUCCESS;
}

