#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define W1_SLAVE_FILE "w1_slave"
#define MAX_SENSORS 10
#define MAX_PATH_LEN 256
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int read_temperature(const char *device_path, float *temperature) {
    char path[MAX_PATH_LEN];
    char buffer[256];
    FILE *fp;
    int ret;

    snprintf(path, sizeof(path), "%s/%s", device_path, W1_SLAVE_FILE);

    fp = fopen(path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    ret = fread(buffer, 1, sizeof(buffer) - 1, fp);
    if (ret < 0) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    buffer[ret] = '\0';

    fclose(fp);

    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for device at %s\n", device_path);
        return -1;
    }

    char *temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found in %s\n", device_path);
        return -1;
    }

    errno = 0;
    long temp_raw = strtol(temp_str + 2, NULL, 10);
    if (errno != 0) {
        fprintf(stderr, "Error parsing temperature from %s: %s\n", device_path, strerror(errno));
        return -1;
    }

    *temperature = (float)temp_raw / 1000.0f;
    return 0;
}

static int find_sensors(char sensor_paths[][MAX_PATH_LEN], int max_sensors) {
    DIR *dir;
    struct dirent *ent;
    int count = 0;

    dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", W1_DEVICES_DIR, strerror(errno));
        return -1;
    }

    while ((ent = readdir(dir)) != NULL) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            if (count < max_sensors) {
                snprintf(sensor_paths[count], MAX_PATH_LEN, "%s/%s", W1_DEVICES_DIR, ent->d_name);
                count++;
            } else {
                fprintf(stderr, "Warning: More than %d sensors found, ignoring remaining.\n", max_sensors);
                break;
            }
        }
    }

    closedir(dir);
    return count;
}

int main(void) {
    char sensor_paths[MAX_SENSORS][MAX_PATH_LEN];
    int num_sensors;
    float temperature;
    int i;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    num_sensors = find_sensors(sensor_paths, MAX_SENSORS);
    if (num_sensors < 0) {
        return 1;
    }

    if (num_sensors == 0) {
        fprintf(stderr, "No DS18B20 sensors found. Check wiring and that the kernel module is loaded.\n");
        return 1;
    }

    printf("Found %d DS18B20 sensor(s).\n", num_sensors);
    for (i = 0; i < num_sensors; i++) {
        printf("  %d: %s\n", i + 1, sensor_paths[i]);
    }
    printf("Reading temperature every %d seconds. Press Ctrl+C to exit.\n\n", READ_INTERVAL_SEC);

    while (keep_running) {
        for (i = 0; i < num_sensors; i++) {
            if (read_temperature(sensor_paths[i], &temperature) == 0) {
                printf("Sensor %d: %.2f °C\n", i + 1, temperature);
            } else {
                fprintf(stderr, "Failed to read temperature from sensor %d.\n", i + 1);
            }
        }
        printf("---\n");
        fflush(stdout);

        for (i = 0; i < READ_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define HTU21D_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define CMD_TEMP_HOLD 0xE3
#define CMD_HUMID_HOLD 0xE5
#define CMD_RESET 0xFE
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int htu21d_reset(int fd) {
    if (i2c_write_byte(fd, CMD_RESET) < 0) return -1;
    usleep(15000);
    return 0;
}

static int htu21d_read_raw(int fd, uint16_t *raw) {
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_byte(fd, CMD_TEMP_HOLD) < 0) return -1;
        usleep(50000);
        if (i2c_read_bytes(fd, buf, 3) < 0) return -1;
        if (buf[2] == 0x00) break;
        retries++;
        usleep(10000);
    }
    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "HTU21D read failed after %d retries\n", MAX_RETRIES);
        return -1;
    }

    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    *raw &= 0xFFFC;
    return 0;
}

static float convert_temperature(uint16_t raw) {
    return -46.85f + (175.72f * (float)raw / 65536.0f);
}

static float convert_humidity(uint16_t raw) {
    float h = -6.0f + (125.0f * (float)raw / 65536.0f);
    if (h < 0.0f) h = 0.0f;
    if (h > 100.0f) h = 100.0f;
    return h;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", HTU21D_ADDR, strerror(errno));
        goto cleanup;
    }

    if (htu21d_reset(fd) < 0) {
        fprintf(stderr, "HTU21D reset failed (sensor absent or bus error)\n");
        goto cleanup;
    }

    while (running) {
        uint16_t raw;
        if (htu21d_read_raw(fd, &raw) < 0) {
            fprintf(stderr, "Failed to read HTU21D data\n");
            goto cleanup;
        }

        float temp = convert_temperature(raw);
        float hum = convert_humidity(raw);

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        fflush(stdout);

        for (int i = 0; i < 60 && running; i++) {
            sleep(1);
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN_1 4
#define GPIO_PIN_2 18
#define CONSUMER "blink_test"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Register signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (GPIO 4)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (GPIO 18)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (GPIO 4)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (GPIO 18)");
        goto cleanup;
    }

    /* Main loop: toggle both lines every 0.05 seconds */
    while (running) {
        int val1 = gpiod_line_get_value(line1);
        if (val1 < 0) {
            perror("gpiod_line_get_value (GPIO 4)");
            goto cleanup;
        }

        int val2 = gpiod_line_get_value(line2);
        if (val2 < 0) {
            perror("gpiod_line_get_value (GPIO 18)");
            goto cleanup;
        }

        /* Toggle both lines */
        if (gpiod_line_set_value(line1, !val1) < 0) {
            perror("gpiod_line_set_value (GPIO 4)");
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, !val2) < 0) {
            perror("gpiod_line_set_value (GPIO 18)");
            goto cleanup;
        }

        printf("GPIO 4: %d, GPIO 18: %d\n", !val1, !val2);
        fflush(stdout);

        usleep(500000); /* 0.05 seconds */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

