    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the two GPIO lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line(GPIO_PIN_1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line(GPIO_PIN_2)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    ret = gpiod_line_request_output(line1, "gpio-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line2, "gpio-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    printf("GPIO %d and %d initialized as outputs. Toggling every %d seconds.\n",
           GPIO_PIN_1, GPIO_PIN_2, POLL_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop: toggle both lines and report */
    while (keep_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "Error reading GPIO values (line1=%d, line2=%d)\n", val1, val2);
            break;
        }

        /* Toggle both lines */
        val1 = !val1;
        val2 = !val2;

        ret = gpiod_line_set_value(line1, val1);
        if (ret < 0) {
            perror("gpiod_line_set_value(line1)");
            break;
        }

        ret = gpiod_line_set_value(line2, val2);
        if (ret < 0) {
            perror("gpiod_line_set_value(line2)");
            break;
        }

        printf("GPIO %d = %d, GPIO %d = %d\n", GPIO_PIN_1, val1, GPIO_PIN_2, val2);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

cleanup:
    /* Ensure lines are low before releasing */
    if (line1) {
        gpiod_line_set_value(line1, 0);
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_set_value(line2, 0);
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    int fd;
    uint8_t buf[6];
    int16_t x, y, z;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to acquire I2C bus access");
        close(fd);
        return EXIT_FAILURE;
    }

    // Enable measurement mode
    uint8_t power_ctl = 0x08;
    if (write(fd, &power_ctl, 1) != 1) {
        perror("Failed to write to power control register");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        if (read(fd, buf, 6) != 6) {
            perror("Failed to read data from ADXL345");
            break;
        }

        x = (int16_t)((buf[1] << 8) | buf[0]);
        y = (int16_t)((buf[3] << 8) | buf[2]);
        z = (int16_t)((buf[5] << 8) | buf[4]);

        printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        usleep(100000); // 0.1 seconds
    }

    // Disable measurement mode
    power_ctl = 0x00;
    if (write(fd, &power_ctl, 1) != 1) {
        perror("Failed to disable ADXL345");
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 27
#define NUM_CYCLES 50
#define DELAY_MS 100

static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    // Set up signal handler for clean exit
    signal(SIGINT, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line as output, initially low
    ret = gpiod_line_request_output(line, "gpio_toggle", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Starting GPIO toggle on GPIO %d for %d cycles...\n", GPIO_LINE, NUM_CYCLES);

    // Main loop
    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        int val = i % 2;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("Failed to set GPIO value");
            break;
        }
        printf("GPIO %d set to %d\n", GPIO_LINE, val);
        usleep(DELAY_MS * 1000);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO toggle complete.\n");
    return EXIT_SUCCESS;
}

