#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_17 17
#define GPIO_18 18

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line18 = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line17) {
        gpiod_line_release(line17);
        line17 = NULL;
    }
    if (line18) {
        gpiod_line_release(line18);
        line18 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line 18");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line17, "gpio17", 0) < 0) {
        perror("gpiod_line_request_output 17");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line18, "gpio18", 0) < 0) {
        perror("gpiod_line_request_output 18");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_value(line17, 1) < 0) {
        perror("gpiod_line_set_value 17");
        cleanup_and_exit(0);
    }
    printf("GPIO 17 set HIGH\n");

    if (gpiod_line_set_value(line18, 1) < 0) {
        perror("gpiod_line_set_value 18");
        cleanup_and_exit(0);
    }
    printf("GPIO 18 set HIGH\n");

    cleanup_and_exit(0);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define DHT22_PIN_1 17
#define DHT22_PIN_2 22
#define DHT22_PIN_3 23
#define DHT22_PIN_4 24

#define MAX_TIMINGS 85
#define DHT_TIMEOUT 1000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(struct gpiod_line *line, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = 1;
    int counter = 0;
    int j = 0, i;

    // Send start signal
    if (gpiod_line_request_output(line, "dht22", 0) < 0) return -1;
    usleep(1000);
    gpiod_line_set_value(line, 1);
    usleep(30000);
    gpiod_line_set_value(line, 0);
    usleep(20000);
    gpiod_line_set_value(line, 1);
    usleep(40);

    // Switch to input
    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    // Read data
    for (i = 0; i < MAX_TIMINGS; i++) {
        counter = 0;
        while (gpiod_line_get_value(line) == laststate) {
            counter++;
            usleep(1);
            if (counter == DHT_TIMEOUT) return -1;
        }
        laststate = gpiod_line_get_value(line);

        if ((i >= 4) && (i % 2 == 0)) {
            data[j / 8] <<= 1;
            if (counter > 16) data[j / 8] |= 1;
            j++;
        }
    }

    // Check checksum
    if ((j >= 40) && (data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF))) {
        *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
        *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
        if (data[2] & 0x80) *temperature = -*temperature;
        return 0;
    }
    return -1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[4];
    float temperature, humidity;
    int ret;

    // Setup signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    lines[0] = gpiod_chip_get_line(chip, DHT22_PIN_1);
    lines[1] = gpiod_chip_get_line(chip, DHT22_PIN_2);
    lines[2] = gpiod_chip_get_line(chip, DHT22_PIN_3);
    lines[3] = gpiod_chip_get_line(chip, DHT22_PIN_4);

    if (!lines[0] || !lines[1] || !lines[2] || !lines[3]) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        for (int i = 0; i < 4; i++) {
            ret = read_dht22(lines[i], &temperature, &humidity);
            if (ret == 0) {
                printf("GPIO %d: Temperature = %.1f C, Humidity = %.1f %%\n", i + 17, temperature, humidity);
            } else {
                fprintf(stderr, "GPIO %d: Error reading DHT22\n", i + 17);
            }
        }
        sleep(2);
    }

    // Cleanup
    gpiod_chip_close(chip);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    int num_pins = sizeof(pins) / sizeof(pins[0]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler.\n");
    }

    while (running) {
        for (int i = 0; i < num_pins; i++) {
            if (gpioPWM(pins[i], 128) != 0) {
                fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM on GPIO %d, %d, %d set to 128/255\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);
        fflush(stdout);

        gpioDelay(DELAY_US);

        for (int i = 0; i < num_pins; i++) {
            if (gpioPWM(pins[i], 0) != 0) {
                fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM on GPIO %d, %d, %d set to 0/255\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);
        fflush(stdout);

        gpioDelay(DELAY_US);
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

