    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are low before releasing */
    if (line17) {
        gpiod_line_set_value(line17, 0);
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_set_value(line18, 0);
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nClean shutdown complete.\n");
    return ret;
}

