#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 22
#define CONSUMER "blink_output"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request line as output, initially low */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Blinking GPIO %d every 0.5 seconds. Press Ctrl+C to exit.\n", GPIO_LINE);

    while (running) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (high)");
            break;
        }
        printf("GPIO %d HIGH\n", GPIO_LINE);
        fflush(stdout);

        sleep(1);

        if (!running) break;

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (low)");
            break;
        }
        printf("GPIO %d LOW\n", GPIO_LINE);
        fflush(stdout);

        sleep(1);
    }

    /* Clean up */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define STEP_DELAY_US 20000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGTERM handler.\n");
    }

    int duty_cycle = 0;
    while (running) {
        if (gpioPWM(PWM_PIN, duty_cycle) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle on GPIO %d.\n", PWM_PIN);
            break;
        }
        printf("Duty cycle: %d\n", duty_cycle);
        fflush(stdout);

        duty_cycle += 10;
        if (duty_cycle > PWM_RANGE) {
            duty_cycle = 0;
        }

        gpioDelay(STEP_DELAY_US);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nPWM stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define NUM_PINS 4
#define DELAY_MS 200

static const unsigned int pins[NUM_PINS] = {17, 22, 23, 24};

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    /* Open GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get lines and request output, initial value low */
    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "gpio-output", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u\n", pins[i]);
            goto cleanup;
        }
    }

    /* Install signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        goto cleanup;
    }

    printf("GPIO output on pins 17, 22, 23, 24. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            int val = (i % 2) ? 1 : 0;
            if (gpiod_line_set_value(lines[i], val) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup;
            }
            printf("Pin %u: %d\n", pins[i], val);
        }
        usleep(DELAY_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg | TCS34725_COMMAND_BIT, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    buf[0] = reg | TCS34725_COMMAND_BIT;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error setting register 0x%02X for read: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (buf[1] << 8) | buf[0];
    return 0;
}

int tcs34725_init(int fd) {
    if (i2c_write_byte(fd, TCS34725_ENABLE, 0x00) < 0) return -1;
    usleep(3000);
    if (i2c_write_byte(fd, TCS34725_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_byte(fd, TCS34725_CONTROL, 0x03) < 0) return -1;
    if (i2c_write_byte(fd, TCS34725_ENABLE, 0x03) < 0) return -1;
    return 0;
}

int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (i2c_read_word(fd, TCS34725_CDATA, clear) < 0) return -1;
    if (i2c_read_word(fd, TCS34725_RDATA, red) < 0) return -1;
    if (i2c_read_word(fd, TCS34725_GDATA, green) < 0) return -1;
    if (i2c_read_word(fd, TCS34725_BDATA, blue) < 0) return -1;
    return 0;
}

int main() {
    int fd = -1;
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", TCS34725_ADDRESS, strerror(errno));
        close(fd);
        return 1;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "Error initializing TCS34725 sensor.\n");
        close(fd);
        return 1;
    }

    printf("TCS34725 initialized successfully.\n");

    while (running) {
        uint16_t clear, red, green, blue;
        if (tcs34725_read_data(fd, &clear, &red, &green, &blue) == 0) {
            printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }
        usleep(200000);
    }

    printf("\nExiting cleanly.\n");
    i2c_write_byte(fd, TCS34725_ENABLE, 0x00);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_18 18
#define GPIO_21 21
#define GPIO_22 22

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line18 = NULL;
static struct gpiod_line *line21 = NULL;
static struct gpiod_line *line22 = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line18) gpiod_line_release(line18);
    if (line21) gpiod_line_release(line21);
    if (line22) gpiod_line_release(line22);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

int main(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Get GPIO lines
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    line21 = gpiod_chip_get_line(chip, GPIO_21);
    line22 = gpiod_chip_get_line(chip, GPIO_22);
    if (!line18 || !line21 || !line22) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(0);
    }

    // Request lines as outputs, initially low
    ret = gpiod_line_request_output(line18, "gpio_output", 0);
    if (ret) {
        perror("gpiod_line_request_output (GPIO 18)");
        cleanup_and_exit(0);
    }
    ret = gpiod_line_request_output(line21, "gpio_output", 0);
    if (ret) {
        perror("gpiod_line_request_output (GPIO 21)");
        cleanup_and_exit(0);
    }
    ret = gpiod_line_request_output(line22, "gpio_output", 0);
    if (ret) {
        perror("gpiod_line_request_output (GPIO 22)");
        cleanup_and_exit(0);
    }

    // Set GPIO states
    gpiod_line_set_value(line18, 1);
    gpiod_line_set_value(line21, 1);
    gpiod_line_set_value(line22, 1);

    // Report states
    printf("GPIO 18: HIGH\n");
    printf("GPIO 21: HIGH\n");
    printf("GPIO 22: HIGH\n");

    // Register signal handler for clean exit
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    // Keep program running until interrupted
    while (1) {
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 4

static int fd = -1;
static void *buffers[NUM_BUFFERS] = {NULL};
static size_t buffer_sizes[NUM_BUFFERS] = {0};

static void cleanup(void) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (buffers[i] && buffers[i] != MAP_FAILED) {
            munmap(buffers[i], buffer_sizes[i]);
            buffers[i] = NULL;
        }
    }
    if (fd >= 0) {
        close(fd);
        fd = -1;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    cleanup();
    exit(EXIT_FAILURE);
}

static int xioctl(int fh, int request, void *arg) {
    int r;
    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);
    return r;
}

static int init_camera(void) {
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    if (fmt.fmt.pix.width != IMAGE_WIDTH || fmt.fmt.pix.height != IMAGE_HEIGHT) {
        fprintf(stderr, "Warning: driver did not accept exact resolution, got %ux%u\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height);
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    for (int i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer %d: %s\n", i, strerror(errno));
            return -1;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            buffers[i] = NULL;
            return -1;
        }
        buffer_sizes[i] = buf.length;
    }

    for (int i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queueing buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int capture_image(unsigned char **image_data, size_t *image_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    *image_data = (unsigned char *)buffers[buf.index];
    *image_size = buf.bytesused;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error re-queueing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int save_image(const unsigned char *image_data, size_t image_size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t written = fwrite(image_data, 1, image_size, fp);
    if (written != image_size) {
        fprintf(stderr, "Error writing to file %s: wrote %zu of %zu bytes\n", filename, written, image_size);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_camera() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    unsigned char *image_data = NULL;
    size_t image_size = 0;

    if (capture_image(&image_data, &image_size) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (save_image(image_data, image_size, "captured.jpg") < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Image captured and saved to captured.jpg\n");

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN_1 22
#define GPIO_PIN_2 27
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 22)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 27)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (pin 22)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (pin 27)");
        goto cleanup;
    }

    /* Main loop: toggle both lines every 10 ms */
    while (running) {
        int val1 = gpiod_line_get_value(line1);
        if (val1 < 0) {
            perror("gpiod_line_get_value (pin 22)");
            goto cleanup;
        }

        int val2 = gpiod_line_get_value(line2);
        if (val2 < 0) {
            perror("gpiod_line_get_value (pin 27)");
            goto cleanup;
        }

        if (gpiod_line_set_value(line1, !val1) < 0) {
            perror("gpiod_line_set_value (pin 22)");
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, !val2) < 0) {
            perror("gpiod_line_set_value (pin 27)");
            goto cleanup;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n",
               GPIO_PIN_1, !val1, GPIO_PIN_2, !val2);
        fflush(stdout);

        usleep(10000); /* 10 ms */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

