static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        perror("i2c_write_byte failed");
        return -1;
    }
    return 0;
}

static int ssd1306_command(int fd, uint8_t cmd) {
    uint8_t buf[2] = {0x00, cmd};
    if (write(fd, buf, 2) != 2) {
        perror("ssd1306_command failed");
        return -1;
    }
    return 0;
}

static int ssd1306_init(int fd) {
    if (ssd1306_command(fd, 0xAE) < 0) return -1;
    if (ssd1306_command(fd, 0xD5) < 0) return -1;
    if (ssd1306_command(fd, 0x80) < 0) return -1;
    if (ssd1306_command(fd, 0xA8) < 0) return -1;
    if (ssd1306_command(fd, SSD1306_HEIGHT - 1) < 0) return -1;
    if (ssd1306_command(fd, 0xD3) < 0) return -1;
    if (ssd1306_command(fd, 0x00) < 0) return -1;
    if (ssd1306_command(fd, 0x40) < 0) return -1;
    if (ssd1306_command(fd, 0x8D) < 0) return -1;
    if (ssd1306_command(fd, 0x14) < 0) return -1;
    if (ssd1306_command(fd, 0x20) < 0) return -1;
    if (ssd1306_command(fd, 0x00) < 0) return -1;
    if (ssd1306_command(fd, 0xA1) < 0) return -1;
    if (ssd1306_command(fd, 0xC8) < 0) return -1;
    if (ssd1306_command(fd, 0xDA) < 0) return -1;
    if (ssd1306_command(fd, 0x12) < 0) return -1;
    if (ssd1306_command(fd, 0x81) < 0) return -1;
    if (ssd1306_command(fd, 0xCF) < 0) return -1;
    if (ssd1306_command(fd, 0xD9) < 0) return -1;
    if (ssd1306_command(fd, 0xF1) < 0) return -1;
    if (ssd1306_command(fd, 0xDB) < 0) return -1;
    if (ssd1306_command(fd, 0x40) < 0) return -1;
    if (ssd1306_command(fd, 0xA4) < 0) return -1;
    if (ssd1306_command(fd, 0xA6) < 0) return -1;
    if (ssd1306_command(fd, 0xAF) < 0) return -1;
    return 0;
}

static int ssd1306_clear(int fd) {
    uint8_t buf[1 + SSD1306_WIDTH];
    buf[0] = 0x40;
    for (int i = 0; i < SSD1306_WIDTH; i++) buf[1 + i] = 0x00;
    for (int page = 0; page < SSD1306_PAGES; page++) {
        if (ssd1306_command(fd, 0xB0 + page) < 0) return -1;
        if (ssd1306_command(fd, 0x00) < 0) return -1;
        if (ssd1306_command(fd, 0x10) < 0) return -1;
        if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
            perror("ssd1306_clear write failed");
            return -1;
        }
    }
    return 0;
}

static int ssd1306_display_number(int fd, int number) {
    if (ssd1306_clear(fd) < 0) return -1;
    char str[16];
    snprintf(str, sizeof(str), "%d", number);
    int len = (int)strlen(str);
    if (len > SSD1306_WIDTH) len = SSD1306_WIDTH;
    int x = (SSD1306_WIDTH - len * 6) / 2;
    int y = (SSD1306_HEIGHT - 8) / 2;
    if (x < 0) x = 0;
    if (y < 0) y = 0;
    if (ssd1306_command(fd, 0xB0 + (y / 8)) < 0) return -1;
    if (ssd1306_command(fd, 0x00 + (x & 0x0F)) < 0) return -1;
    if (ssd1306_command(fd, 0x10 + ((x >> 4) & 0x0F)) < 0) return -1;
    uint8_t buf[1 + len * 6];
    buf[0] = 0x40;
    for (int i = 0; i < len; i++) {
        int c = (int)str[i] - 32;
        if (c < 0 || c > 95) c = 0;
        for (int j = 0; j < 5; j++) {
            buf[1 + i * 6 + j] = font5x7[c][j];
        }
        buf[1 + i * 6 + 5] = 0x00;
    }
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        perror("ssd1306_display_number write failed");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(fd);
        return 1;
    }

    if (ssd1306_init(fd) < 0) {
        fprintf(stderr, "SSD1306 initialization failed\n");
        close(fd);
        return 1;
    }

    int number = 0;
    while (running) {
        if (ssd1306_display_number(fd, number) < 0) {
            fprintf(stderr, "Failed to display number\n");
            break;
        }
        number++;
        usleep(100000);
    }

    ssd1306_command(fd, 0xAE);
    close(fd);
    return 0;
}

