    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 8
static const unsigned int pins[NUM_PINS] = {1, 4, 5, 6, 21, 22, 23, 24};

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "gpio-output", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        int val = gpiod_line_get_value(lines[i]);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value failed for pin %u\n", pins[i]);
            goto cleanup;
        }
        printf("GPIO %u: %d\n", pins[i], val);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 4
#define CAPTURE_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fh, int request, void *arg) {
    int r;
    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);
    return r;
}

static int init_camera(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    *fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (*fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(*fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Warning: device does not support MJPEG, using %c%c%c%c\n",
                fmt.fmt.pix.pixelformat & 0xFF,
                (fmt.fmt.pix.pixelformat >> 8) & 0xFF,
                (fmt.fmt.pix.pixelformat >> 16) & 0xFF,
                (fmt.fmt.pix.pixelformat >> 24) & 0xFF);
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(*fd);
        return -1;
    }

    for (i = 0; i < req.count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer %u: %s\n", i, strerror(errno));
            close(*fd);
            return -1;
        }

        void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);
        if (MAP_FAILED == buffer) {
            fprintf(stderr, "Error mapping buffer %u: %s\n", i, strerror(errno));
            close(*fd);
            return -1;
        }

        if (xioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queueing buffer %u: %s\n", i, strerror(errno));
            munmap(buffer, buf.length);
            close(*fd);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

static int capture_image(int fd, unsigned char **image_data, size_t *image_size) {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Select timeout\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    *image_data = malloc(buf.bytesused);
    if (!*image_data) {
        fprintf(stderr, "Error allocating memory for image\n");
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    memcpy(*image_data, (unsigned char *)mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset), buf.bytesused);
    *image_size = buf.bytesused;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queueing buffer: %s\n", strerror(errno));
        free(*image_data);
        *image_data = NULL;
        return -1;
    }

    return 0;
}

static int save_image(const unsigned char *image_data, size_t image_size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t written = fwrite(image_data, 1, image_size, fp);
    if (written != image_size) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static void cleanup(int fd) {
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
    }
}

int main(void) {
    int fd = -1;
    unsigned char *image_data = NULL;
    size_t image_size = 0;
    int ret = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_camera(&fd) < 0) {
        return 1;
    }

    while (running) {
        if (capture_image(fd, &image_data, &image_size) < 0) {
            fprintf(stderr, "Error capturing image\n");
            ret = 1;
            break;
        }

        if (save_image(image_data, image_size, "image.jpg") < 0) {
            fprintf(stderr, "Error saving image\n");
            ret = 1;
            break;
        }

        free(image_data);
        image_data = NULL;
        image_size = 0;

        usleep(CAPTURE_INTERVAL_US);
    }

    cleanup(fd);
    free(image_data);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7
#define BME280_REG_CALIB00 0x88
#define BME280_REG_CALIB26 0xE1

#define BME280_CHIP_ID 0x60
#define BME280_RESET_CMD 0xB6

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    if (write(i2c_fd, &reg, 1) != 1) return -1;
    if (read(i2c_fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(i2c_fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) return -1;
    if (read(i2c_fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int bme280_read_calibration(int fd, uint16_t *dig_T1, int16_t *dig_T2, int16_t *dig_T3,
                                  uint16_t *dig_P1, int16_t *dig_P2, int16_t *dig_P3,
                                  int16_t *dig_P4, int16_t *dig_P5, int16_t *dig_P6,
                                  int16_t *dig_P7, int16_t *dig_P8, int16_t *dig_P9,
                                  uint8_t *dig_H1, int16_t *dig_H2, uint8_t *dig_H3,
                                  int16_t *dig_H4, int16_t *dig_H5, int8_t *dig_H6) {
    uint8_t buf[26];
    if (i2c_read_block(BME280_REG_CALIB00, buf, 26) < 0) return -1;
    *dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    *dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    *dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    *dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    *dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    *dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    *dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    *dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    *dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    *dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    *dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    *dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    *dig_H1 = buf[25];

    uint8_t buf2[7];
    if (i2c_read_block(BME280_REG_CALIB26, buf2, 7) < 0) return -1;
    *dig_H2 = (int16_t)(buf2[0] | (buf2[1] << 8));
    *dig_H3 = buf2[2];
    *dig_H4 = (int16_t)((buf2[3] << 4) | (buf2[4] & 0x0F));
    *dig_H5 = (int16_t)((buf2[5] << 4) | (buf2[4] >> 4));
    *dig_H6 = (int8_t)buf2[6];
    return 0;
}

static int bme280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(BME280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != BME280_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X (expected 0x%02X)\n", id, BME280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(BME280_REG_RESET, BME280_RESET_CMD) < 0) {
        fprintf(stderr, "Error resetting BME280: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    uint8_t status;
    for (int i = 0; i < 10; i++) {
        if (i2c_read_reg(BME280_REG_STATUS, &status) < 0) {
            fprintf(stderr, "Error reading status: %s\n", strerror(errno));
            return -1;
        }
        if ((status & 0x01) == 0) break;
        usleep(2000);
    }
    if (status & 0x01) {
        fprintf(stderr, "BME280 reset timeout\n");
        return -1;
    }

    if (i2c_write_reg(BME280_REG_CTRL_HUM, 0x01) < 0) return -1;
    if (i2c_write_reg(BME280_REG_CONFIG, 0xA0) < 0) return -1;
    if (i2c_write_reg(BME280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    return 0;
}

static int bme280_read_raw(int fd, int32_t *temp, int32_t *press, int32_t *hum) {
    uint8_t buf[8];
    if (i2c_read_block(BME280_REG_DATA, buf, 8) < 0) return -1;
    *press = (int32_t)((buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4));
    *temp = (int32_t)((buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4));
    *hum = (int32_t)((buf[6] << 8) | buf[7]);
    return 0;
}

static int32_t compensate_temp(int32_t raw, int32_t *t_fine) {
    int32_t var1, var2;
    var1 = ((((raw >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    var2 = (((((raw >> 4) - ((int32_t)dig_T1)) * ((raw >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_press(int32_t raw, int32_t t_fine) {
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)dig_P6;
    var2 = var2 + ((var1 * (int64_t)dig_P5) << 17);
    var2 = var2 + (((int64_t)dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)dig_P3) >> 8) + ((var1 * (int64_t)dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)dig_P1) >> 33;
    if (var1 == 0) return 0;
    p = 1048576 - raw;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)dig_P7) << 4);
    return (uint32_t)p;
}

static uint32_t compensate_hum(int32_t raw, int32_t t_fine) {
    int32_t v_x1;
    v_x1 = t_fine - 76800;
    v_x1 = (((((raw << 14) - (((int32_t)dig_H4) << 20) - (((int32_t)dig_H5) * v_x1)) + 16384) >> 15) * (((((((v_x1 * ((int32_t)dig_H6)) >> 10) * (((v_x1 * ((int32_t)dig_H3)) >> 11) + 32768)) >> 10) + 2097152) * ((int32_t)dig_H2) + 8192) >> 14));
    v_x1 = v_x1 - (((((v_x1 >> 15) * (v_x1 >> 15)) >> 7) * ((int32_t)dig_H1)) >> 4);
    if (v_x1 < 0) v_x1 = 0;
    if (v_x1 > 419430400) v_x1 = 419430400;
    return (uint32_t)(v_x1 >> 12);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (bme280_init(i2c_fd) < 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    uint16_t dig_T1; int16_t dig_T2, dig_T3, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
    uint8_t dig_H1; int16_t dig_H2; uint8_t dig_H3; int16_t dig_H4, dig_H5; int8_t dig_H6;
    if (bme280_read_calibration(i2c_fd, &dig_T1, &dig_T2, &dig_T3, &dig_P1, &dig_P2, &dig_P3, &dig_P4, &dig_P5, &dig_P6, &dig_P7, &dig_P8, &dig_P9, &dig_H1, &dig_H2, &dig_H3, &dig_H4, &dig_H5, &dig_H6) < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (running) {
        int32_t raw_t, raw_p, raw_h, t_fine;
        if (bme280_read_raw(i2c_fd, &raw_t, &raw_p, &raw_h) < 0) {
            fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
            break;
        }
        int32_t temp = compensate_temp(raw_t, &t_fine);
        uint32_t press = compensate_press(raw_p, t_fine);
        uint32_t hum = compensate_hum(raw_h, t_fine);
        printf("Temperature: %.2f C, Pressure: %.2f hPa, Humidity: %.2f %%\n", temp / 100.0, press / 100.0, hum / 1024.0);
        sleep(5);
    }

    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_AIN0_GND (0x4 << 12)
#define ADS1115_CONFIG_PGA_4_096V (0x1 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (1 << 8)
#define ADS1115_CONFIG_DR_128SPS (0x4 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x3 << 0)

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_read_channel(int fd, uint16_t *raw) {
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) < 0) {
        return -1;
    }

    usleep(10000);

    uint16_t cfg;
    if (i2c_read_reg16(fd, ADS1115_REG_CONFIG, &cfg) < 0) {
        return -1;
    }

    if (!(cfg & ADS1115_CONFIG_OS_BEGIN)) {
        return -1;
    }

    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, raw) < 0) {
        return -1;
    }

    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access to 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("ADS1115 initialized. Sampling AIN0 every 0.2 seconds. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t raw;
        if (ads1115_read_channel(fd, &raw) < 0) {
            fprintf(stderr, "Error reading ADS1115: %s\n", strerror(errno));
            break;
        }

        int16_t signed_raw = (int16_t)raw;
        float voltage = (signed_raw * 4.096) / 32768.0;
        printf("AIN0: %.3f V\n", voltage);
        fflush(stdout);

        usleep(200000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
