#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int mpu6050_init(int fd) {
    uint8_t who_am_i;
    if (i2c_read_reg8(fd, 0x75, &who_am_i) != 0) {
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "MPU6050 not found (WHO_AM_I=0x%02X, expected 0x68)\n", who_am_i);
        return -1;
    }
    if (i2c_read_reg8(fd, PWR_MGMT_1, &who_am_i) != 0) {
        return -1;
    }
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) != 0) {
        return -1;
    }
    usleep(100000);
    return 0;
}

int main(void) {
    int fd = -1;
    int16_t ax, ay, az;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (mpu6050_init(fd) != 0) {
        fprintf(stderr, "MPU6050 initialization failed\n");
        close(fd);
        return 1;
    }

    printf("MPU6050 initialized. Reading accelerometer data...\n");

    while (running) {
        if (i2c_read_reg16(fd, ACCEL_XOUT_H, &ax) != 0 ||
            i2c_read_reg16(fd, ACCEL_YOUT_H, &ay) != 0 ||
            i2c_read_reg16(fd, ACCEL_ZOUT_H, &az) != 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
            break;
        }
        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", ax, ay, az);
        usleep(100000);
    }

    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return 0;
}

