#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define LCD_ADDR 0x27

#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04

static int lcd_fd = -1;
static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

void lcd_byte(int bits, int mode) {
    int bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;

    if (write(lcd_fd, (uint8_t *)&bits_high, 1) != 1) {
        perror("Error writing high bits");
        return;
    }
    usleep(1000);
    if (write(lcd_fd, (uint8_t *)&bits_high | ENABLE, 1) != 1) {
        perror("Error enabling high bits");
        return;
    }
    usleep(1000);
    if (write(lcd_fd, (uint8_t *)&bits_high, 1) != 1) {
        perror("Error disabling high bits");
        return;
    }
    usleep(1000);

    if (write(lcd_fd, (uint8_t *)&bits_low, 1) != 1) {
        perror("Error writing low bits");
        return;
    }
    usleep(1000);
    if (write(lcd_fd, (uint8_t *)&bits_low | ENABLE, 1) != 1) {
        perror("Error enabling low bits");
        return;
    }
    usleep(1000);
    if (write(lcd_fd, (uint8_t *)&bits_low, 1) != 1) {
        perror("Error disabling low bits");
        return;
    }
    usleep(1000);
}

void lcd_string(const char *s) {
    while (*s) {
        lcd_byte((uint8_t)*s, LCD_CHR);
        s++;
    }
}

void lcd_clear() {
    lcd_byte(0x01, LCD_CMD);
    usleep(2000);
}

void lcd_init() {
    usleep(50000);
    lcd_byte(0x33, LCD_CMD);
    lcd_byte(0x32, LCD_CMD);
    lcd_byte(0x28, LCD_CMD);
    lcd_byte(0x0C, LCD_CMD);
    lcd_byte(0x06, LCD_CMD);
    lcd_byte(0x01, LCD_CMD);
    usleep(2000);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    lcd_fd = open(I2C_BUS, O_RDWR);
    if (lcd_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (ioctl(lcd_fd, I2C_SLAVE, LCD_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(lcd_fd);
        return 1;
    }

    lcd_init();

    while (running) {
        lcd_clear();
        lcd_string("Hello World!");
        lcd_byte(LCD_LINE_2, LCD_CMD);
        lcd_string("Raspberry Pi");
        sleep(10);
    }

    lcd_clear();
    close(lcd_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_reg8(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t val;
    if (read(fd, &val, 1) != 1) return -1;
    return val;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(fd);
        return 1;
    }

    int whoami = i2c_read_reg8(fd, 0x75);
    if (whoami != 0x68) {
        fprintf(stderr, "MPU6050 not found (WHO_AM_I=0x%02X)\n", whoami);
        close(fd);
        return 1;
    }

    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        perror("Failed to wake up MPU6050");
        close(fd);
        return 1;
    }

    for (int i = 0; i < 100 && running; i++) {
        uint8_t buf[6];
        if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) {
            perror("Failed to read accelerometer data");
            close(fd);
            return 1;
        }

        int16_t ax = (buf[0] << 8) | buf[1];
        int16_t ay = (buf[2] << 8) | buf[3];
        int16_t az = (buf[4] << 8) | buf[5];

        printf("Accel X: %d, Y: %d, Z: %d\n", ax, ay, az);
        usleep(10000);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_14 14
#define GPIO_15 15
#define CONSUMER "gpio_output"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line14 = NULL;
    struct gpiod_line *line15 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line14 = gpiod_chip_get_line(chip, GPIO_14);
    if (!line14) {
        perror("gpiod_chip_get_line(GPIO 14)");
        goto cleanup;
    }

    line15 = gpiod_chip_get_line(chip, GPIO_15);
    if (!line15) {
        perror("gpiod_chip_get_line(GPIO 15)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    ret = gpiod_line_request_output(line14, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(GPIO 14)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line15, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(GPIO 15)");
        goto cleanup;
    }

    printf("GPIO %d and %d set to output. Press Ctrl+C to exit.\n", GPIO_14, GPIO_15);

    /* Main loop: toggle the two lines every POLL_INTERVAL_SEC seconds */
    while (keep_running) {
        ret = gpiod_line_set_value(line14, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO 14, 1)");
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_14);

        ret = gpiod_line_set_value(line15, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO 15, 1)");
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_15);

        sleep(POLL_INTERVAL_SEC);

        if (!keep_running) {
            break;
        }

        ret = gpiod_line_set_value(line14, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO 14, 0)");
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_14);

        ret = gpiod_line_set_value(line15, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO 15, 0)");
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_15);

        sleep(POLL_INTERVAL_SEC);
    }

    /* Ensure lines are left low on exit */
    gpiod_line_set_value(line14, 0);
    gpiod_line_set_value(line15, 0);

cleanup:
    if (line14) {
        gpiod_line_release(line14);
    }
    if (line15) {
        gpiod_line_release(line15);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
