#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_sensor_publisher"
#define MQTT_TOPIC "sensor_data"
#define SAMPLE_INTERVAL_US 100000  /* 0.01 seconds */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 1000000     /* 1 second */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a sensor value from the connected device.
 * Returns 0 on success, -1 on failure.
 */
static int read_sensor(int *value) {
    /*
     * In a real application, this function would read from the
     * connected device via I2C or SPI. For this example, we simulate
     * a sensor reading by generating a random number between 0 and 100.
     */
    *value = rand() % 101;
    return 0;
}

/*
 * Validate the sensor reading.
 * Returns 0 if the reading is valid, -1 if it is invalid.
 */
static int validate_sensor_reading(int value) {
    if (value < 0 || value > 100) {
        fprintf(stderr, "Error: Invalid sensor reading: %d\n", value);
        return -1;
    }
    return 0;
}

/*
 * Publish the sensor reading to the MQTT broker.
 * Returns 0 on success, -1 on failure.
 */
static int publish_sensor_reading(MQTTClient client, int value) {
    char payload[32];
    int payloadlen = snprintf(payload, sizeof(payload), "%d", value);
    if (payloadlen < 0 || (size_t)payloadlen >= sizeof(payload)) {
        fprintf(stderr, "Error: Failed to format payload\n");
        return -1;
    }

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = payloadlen;
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to publish message, return code %d\n", rc);
        return -1;
    }

    rc = MQTTClient_waitForCompletion(client, token, 1000000); /* 1 second timeout */
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to wait for completion, return code %d\n", rc);
        return -1;
    }

    return 0;
}

