    MQTTClient client;
    int rc;
    int sensor_value;
    int retries;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Seed the random number generator */
    srand(time(NULL));

    /* Set up signal handling for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MQTT client */
    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID,
                      MQTTCLIENT_PERSISTENCE_NONE, NULL);

    /* Connect to the MQTT broker */
    rc = MQTTClient_connect(client, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to connect to MQTT broker, return code %d\n", rc);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Connected to MQTT broker at %s\n", MQTT_BROKER_ADDRESS);

    /* Main loop */
    while (running) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_sensor(&sensor_value) == 0) {
                if (validate_sensor_reading(sensor_value) == 0) {
                    if (publish_sensor_reading(client, sensor_value) == 0) {
                        printf("Published sensor reading: %d\n", sensor_value);
                        break; /* Exit retry loop on success */
                    } else {
                        fprintf(stderr, "Error publishing sensor reading, retrying...\n");
                    }
                } else {
                    fprintf(stderr, "Invalid sensor reading, retrying...\n");
                }
            } else {
                fprintf(stderr, "Error reading sensor, retrying...\n");
            }
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(RETRY_DELAY_US);
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor after %d retries, skipping sample\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean up */
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

