#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    22
#define ECHO_PIN2   27

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MAX_DISTANCE_CM          400.0
#define MIN_DISTANCE_CM          2.0
#define TIMEOUT_US               30000
#define LOOP_DELAY_US            100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static int wait_for_level(struct gpiod_line *line, int level, long long deadline_us) {
    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            return -1;
        }
        if (val == level) return 0;
        if (now_us() > deadline_us) return -1;
    }
    return -1;
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo, float *distance) {
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(0)");
        return -1;
    }
    usleep(2);

    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value(1)");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(0)");
        return -1;
    }

    long long deadline = now_us() + TIMEOUT_US;
    if (wait_for_level(echo, 1, deadline) < 0) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1;
    }

    long long start = now_us();
    if (wait_for_level(echo, 0, deadline) < 0) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1;
    }
    long long end = now_us();

    long long diff = end - start;
    if (diff <= 0) {
        fprintf(stderr, "Invalid pulse width\n");
        return -1;
    }

    float dist = (float)diff * SPEED_OF_SOUND_CM_PER_US / 2.0f;
    if (dist < MIN_DISTANCE_CM || dist > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", dist);
        return -1;
    }

    *distance = dist;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    struct gpiod_line *echo2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    echo2 = gpiod_chip_get_line(chip, ECHO_PIN2);
    if (!trig || !echo || !echo2) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo2, "hcsr04") < 0) {
        perror("gpiod_line_request_input(echo2)");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        float d1 = 0.0f, d2 = 0.0f;
        int ok1 = measure_distance(trig, echo, &d1);
        int ok2 = measure_distance(trig, echo2, &d2);

        if (ok1 == 0 && ok2 == 0) {
            printf("Distance 1: %.2f cm, Distance 2: %.2f cm\n", d1, d2);
        } else if (ok1 == 0) {
            printf("Distance 1: %.2f cm, Distance 2: ERROR\n", d1);
        } else if (ok2 == 0) {
            printf("Distance 1: ERROR, Distance 2: %.2f cm\n", d2);
        } else {
            printf("Distance 1: ERROR, Distance 2: ERROR\n");
        }

        usleep(LOOP_DELAY_US);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (echo2) gpiod_line_release(echo2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

