#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <stdbool.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_sensor_publisher"
#define MQTT_TOPIC "sensor_data"
#define MQTT_QOS 1
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int *sensor_value) {
    /*
     * Simulate a sensor reading.
     * In a real application, this would read from a connected device.
     */
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return -1;
    }
    *sensor_value = (int)(now % 100);
    return 0;
}

static int publish_sensor_data(MQTTClient client, int sensor_value) {
    char payload[32];
    int payload_len = snprintf(payload, sizeof(payload), "%d", sensor_value);
    if (payload_len < 0 || (size_t)payload_len >= sizeof(payload)) {
        fprintf(stderr, "Error formatting payload\n");
        return -1;
    }

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = payload_len;
    pubmsg.qos = MQTT_QOS;
    pubmsg.retained = 0;

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        return -1;
    }

    rc = MQTTClient_waitForCompletion(client, token, 10000);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to wait for publish completion, return code %d\n", rc);
        return -1;
    }

    return 0;
}

int main(void) {
    MQTTClient client;
    int rc;

    /* Initialize pigpio for GPIO access (optional, but used in the simulated read) */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize MQTT client */
    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);

    /* Set signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Connect to MQTT broker */
    rc = MQTTClient_connect(client, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Connected to MQTT broker at %s\n", MQTT_BROKER_ADDRESS);

    /* Main loop */
    while (running) {
        int sensor_value;
        if (read_sensor_data(&sensor_value) != 0) {
            fprintf(stderr, "Error reading sensor data\n");
            break;
        }

        if (publish_sensor_data(client, sensor_value) != 0) {
            fprintf(stderr, "Error publishing sensor data\n");
            break;
        }

        printf("Published sensor value: %d\n", sensor_value);

        /* Sleep for the sample interval, checking running flag periodically */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    /* Disconnect from MQTT broker */
    rc = MQTTClient_disconnect(client, 1000);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to disconnect from MQTT broker, return code %d\n", rc);
    }

    /* Destroy MQTT client */
    MQTTClient_destroy(&client);

    /* Terminate pigpio */
    gpioTerminate();

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQUENCY 1000
#define LOOP_DELAY_US 5000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure PWM pin */
    ret = gpioSetMode(PWM_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %d\n", PWM_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPWMrange(PWM_PIN, PWM_RANGE);
    if (ret != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d: %d\n", PWM_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    if (ret != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d: %d\n", PWM_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main loop: apply PWM and report state */
    while (running) {
        ret = gpioPWM(PWM_PIN, PWM_RANGE);
        if (ret != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d: %d\n", PWM_PIN, ret);
            break;
        }
        printf("PWM applied to GPIO %d (range %d, freq %d Hz)\n", PWM_PIN, PWM_RANGE, PWM_FREQUENCY);
        fflush(stdout);

        /* Sleep for 5 seconds, checking running flag every 100 ms */
        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(100000);
        }
    }

    /* Clean shutdown: stop PWM and terminate pigpio */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nPWM stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

