    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static int wait_for_level(struct gpiod_line *line, int target, long long deadline_us) {
    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            return -1;
        }
        if (val == target) return 0;
        if (now_us() > deadline_us) return -1;  /* timeout */
    }
    return -1;
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(0)");
        return -1;
    }
    usleep(2);

    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value(1)");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(0)");
        return -1;
    }

    long long deadline = now_us() + TIMEOUT_US;
    if (wait_for_level(echo, 1, deadline) < 0) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1;
    }

    long long start = now_us();
    if (wait_for_level(echo, 0, deadline) < 0) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1;
    }
    long long end = now_us();

    long long diff = end - start;
    if (diff < 0) {
        fprintf(stderr, "Clock error\n");
        return -1;
    }

    double distance = (double)diff * SOUND_SPEED_CM_S / 2000000.0;
    if (distance < 2.0 || distance > 400.0) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1;
    }

    return (int)(distance + 0.5);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = measure_distance(trig, echo);
        if (distance >= 0) {
            printf("Distance: %d cm\n", distance);
        } else {
            fprintf(stderr, "Measurement failed\n");
        }
        usleep(LOOP_DELAY_US);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 23

#define PWM_RANGE 255
#define PWM_FREQ 1000

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_4, PWM_RANGE);

    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQ);

    while (running) {
        gpioPWM(PWM_PIN_1, 128);
        gpioPWM(PWM_PIN_2, 128);
        gpioPWM(PWM_PIN_3, 128);
        gpioPWM(PWM_PIN_4, 128);
        printf("PWM: 17=128, 18=128, 22=128, 23=128\n");
        gpioDelay(100000);

        gpioPWM(PWM_PIN_1, 0);
        gpioPWM(PWM_PIN_2, 0);
        gpioPWM(PWM_PIN_3, 0);
        gpioPWM(PWM_PIN_4, 0);
        printf("PWM: 17=0, 18=0, 22=0, 23=0\n");
        gpioDelay(100000);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <paho-mqtt-c/MQTTClient.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x40
#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_TOPIC "sensor/temperature"
#define MQTT_CLIENT_ID "rpi_sensor"
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define MAX_READ_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static MQTTClient mqtt_client;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_init(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", I2C_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int i2c_read_temperature(float *temperature) {
    unsigned char buf[2];
    int retries = 0;
    int delay_ms = 10;

    while (retries < MAX_RETRIES) {
        ssize_t bytes_read = read(i2c_fd, buf, 2);
        if (bytes_read == 2) {
            int raw_temp = (buf[0] << 8) | buf[1];
            *temperature = (float)raw_temp / 100.0f;
            return 0;
        }
        fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n", retries + 1, MAX_RETRIES, strerror(errno));
        retries++;
        if (retries < MAX_RETRIES) {
            usleep(delay_ms * 1000);
            delay_ms *= 2;
        }
    }
    return -1;
}

static int mqtt_init(void) {
    int rc;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

    MQTTClient_create(&mqtt_client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(mqtt_client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&mqtt_client);
        return -1;
    }
    return 0;
}

static int mqtt_publish(const char *topic, const char *payload) {
    int rc;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;

    pubmsg.payload = (void *)payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    rc = MQTTClient_publishMessage(mqtt_client, topic, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
        return -1;
    }
    rc = MQTTClient_waitForCompletion(mqtt_client, token, 10000);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to wait for publish completion: %s\n", MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (mqtt_client) {
        MQTTClient_disconnect(mqtt_client, 1000);
        MQTTClient_destroy(&mqtt_client);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    float temperature;
    char payload[64];
    time_t now;
    struct tm *timeinfo;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if (i2c_init() != 0) {
        return 1;
    }

    if (mqtt_init() != 0) {
        cleanup();
        return 1;
    }

    while (running) {
        if (i2c_read_temperature(&temperature) == 0) {
            time(&now);
            timeinfo = localtime(&now);
            strftime(payload, sizeof(payload), "%Y-%m-%dT%H:%M:%S", timeinfo);
            snprintf(payload + strlen(payload), sizeof(payload) - strlen(payload), ",%.2f", temperature);

            if (mqtt_publish(MQTT_TOPIC, payload) != 0) {
                fprintf(stderr, "Failed to publish temperature reading.\n");
            } else {
                printf("Published: %s\n", payload);
            }
        } else {
            fprintf(stderr, "Failed to read temperature from sensor.\n");
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_sensor_node"
#define MQTT_TOPIC "sensor_data"
#define NUM_READINGS 10
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_OS_BEGIN 0x8000
#define ADS1115_MUX_AIN0 0x4000
#define ADS1115_PGA_4_096V 0x0200
#define ADS1115_MODE_SINGLE 0x0100
#define ADS1115_DR_128SPS 0x0080
#define ADS1115_CQUE_NONE 0x0003

static volatile sig_atomic_t running = 1;
static MQTTClient client;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_ads1115(int handle, float *voltage) {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_OS_BEGIN | ADS1115_MUX_AIN0 | ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS | ADS1115_CQUE_NONE) >> 8;
    config[2] = (ADS1115_OS_BEGIN | ADS1115_MUX_AIN0 | ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS | ADS1115_CQUE_NONE) & 0xFF;

    if (i2cWriteDevice(handle, config, 3) != 0) {
        fprintf(stderr, "Error writing config to ADS1115\n");
        return -1;
    }

    gpioDelay(10000);

    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error selecting conversion register\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading conversion data\n");
        return -1;
    }

    int16_t raw = (data[0] << 8) | data[1];
    *voltage = (raw * 4.096) / 32768.0;
    return 0;
}

int publish_data(MQTTClient client, const char *topic, float voltage) {
    char payload[64];
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    strftime(payload, sizeof(payload), "%Y-%m-%d %H:%M:%S", t);
    snprintf(payload + strlen(payload), sizeof(payload) - strlen(payload), ",%.2f", voltage);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(client, topic, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        return -1;
    }

    rc = MQTTClient_waitForCompletion(client, token, 10000L);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to wait for completion, return code %d\n", rc);
        return -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc;

    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    for (int i = 0; i < NUM_READINGS && running; i++) {
        float voltage;
        if (read_ads1115(i2c_handle, &voltage) == 0) {
            if (publish_data(client, MQTT_TOPIC, voltage) != 0) {
                fprintf(stderr, "Failed to publish data\n");
            } else {
                printf("Published reading: %.2f V\n", voltage);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(1000000);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_18 18
#define CONSUMER "gpio-toggle"
#define PERIOD_US 50000  /* 0.05 seconds */

static volatile sig_atomic_t keep_running = 1;

static void handle_sigint(int sig)
{
    (void)sig;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line(GPIO 17)");
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line(GPIO 18)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    ret = gpiod_line_request_output(line17, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(GPIO 17)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line18, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(GPIO 18)");
        goto cleanup;
    }

    printf("GPIO 17 and GPIO 18 toggled every 0.05 seconds. Press Ctrl+C to exit.\n");

    while (keep_running) {
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO 17 high)");
            goto cleanup;
        }
        printf("GPIO 17 HIGH\n");

        ret = gpiod_line_set_value(line18, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO 18 low)");
            goto cleanup;
        }
        printf("GPIO 18 LOW\n");

        usleep(PERIOD_US);

        if (!keep_running)
            break;

        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO 17 low)");
            goto cleanup;
        }
        printf("GPIO 17 LOW\n");

        ret = gpiod_line_set_value(line18, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO 18 high)");
            goto cleanup;
        }
        printf("GPIO 18 HIGH\n");

        usleep(PERIOD_US);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line17)
        gpiod_line_release(line17);
    if (line18)
        gpiod_line_release(line18);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Set up signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request line as output, initially low */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to output. Press Ctrl+C to exit.\n", GPIO_LINE);

    /* Main loop: toggle every 5 seconds */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        val = !val;

        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE, val);

        /* Sleep 5 seconds, checking for interrupt every second */
        for (int i = 0; i < 5 && keep_running; i++) {
            sleep(1);
        }
    }

    /* Clean up */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_23 23

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line23 = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line17) {
        gpiod_line_release(line17);
        line17 = NULL;
    }
    if (line23) {
        gpiod_line_release(line23);
        line23 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    line23 = gpiod_chip_get_line(chip, GPIO_23);
    if (!line23) {
        perror("gpiod_chip_get_line 23");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line17, "gpio17-output", 0) < 0) {
        perror("gpiod_line_request_output 17");
        gpiod_line_release(line17);
        gpiod_line_release(line23);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line23, "gpio23-output", 0) < 0) {
        perror("gpiod_line_request_output 23");
        gpiod_line_release(line17);
        gpiod_line_release(line23);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_value(line17, 1) < 0) {
        perror("gpiod_line_set_value 17");
        cleanup_and_exit(0);
    }
    printf("GPIO 17 set to HIGH\n");

    if (gpiod_line_set_value(line23, 1) < 0) {
        perror("gpiod_line_set_value 23");
        cleanup_and_exit(0);
    }
    printf("GPIO 23 set to HIGH\n");

    cleanup_and_exit(0);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 22
#define POLL_INTERVAL_US 100000  /* 0.1 seconds */

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for BCM 22 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, "gpio22-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d (BCM) toggled every 0.1 seconds. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    /* Main loop: toggle the line and report the state */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        val = !val;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, val);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B115200

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int fd;
    struct termios tty;
    char buffer[256];
    ssize_t bytes_read;

    // Set up signal handler for clean exit
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open serial port
    fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening serial port");
        return EXIT_FAILURE;
    }

    // Configure serial port
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return EXIT_FAILURE;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit characters
    tty.c_iflag &= ~IGNBRK;                        // Disable break processing
    tty.c_lflag = 0;                                // Non-canonical mode
    tty.c_oflag = 0;                                // No output processing
    tty.c_cc[VMIN] = 0;                             // Read without timeout
    tty.c_cc[VTIME] = 5;                            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);         // Disable software flow control
    tty.c_cflag |= (CLOCAL | CREAD);                // Enable receiver, ignore modem control
    tty.c_cflag &= ~(PARENB | PARODD);              // No parity
    tty.c_cflag &= ~CSTOPB;                         // 1 stop bit
    tty.c_cflag &= ~CRTSCTS;                        // Disable hardware flow control

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return EXIT_FAILURE;
    }

    // Flush any stale data
    tcflush(fd, TCIOFLUSH);

    printf("Serial port initialized on %s at 115200 baud.\n", SERIAL_PORT);

    // Main loop
    while (running) {
        bytes_read = read(fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s", buffer);
            fflush(stdout);
        } else if (bytes_read == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue; // Timeout, no data available
            }
            perror("Error reading from serial port");
            break;
        } else {
            // bytes_read == 0, no data available
            continue;
        }
    }

    // Clean up
    close(fd);
    printf("\nSerial port closed.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

int main() {
    int fd = -1;
    int16_t accel_x, accel_y, accel_z;
    uint8_t buf[6];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t who_am_i;
    if (i2c_read_reg8(fd, 0x75, &who_am_i) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "MPU6050 not found (WHO_AM_I=0x%02X, expected 0x68)\n", who_am_i);
        close(fd);
        return 1;
    }

    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) {
            fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
            break;
        }

        accel_x = (int16_t)((buf[0] << 8) | buf[1]);
        accel_y = (int16_t)((buf[2] << 8) | buf[3]);
        accel_z = (int16_t)((buf[4] << 8) | buf[5]);

        printf("Accel X: %d, Y: %d, Z: %d\n", accel_x, accel_y, accel_z);
        usleep(100000);
    }

    if (fd >= 0) {
        close(fd);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define BMP280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88

#define BMP280_CHIP_ID 0x58

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int bmp280_read_calibration(int fd, uint16_t *dig_T1, int16_t *dig_T2, int16_t *dig_T3,
                                   uint16_t *dig_P1, int16_t *dig_P2, int16_t *dig_P3,
                                   int16_t *dig_P4, int16_t *dig_P5, int16_t *dig_P6,
                                   int16_t *dig_P7, int16_t *dig_P8, int16_t *dig_P9) {
    uint8_t calib[24];
    if (i2c_read_block(fd, BMP280_REG_CALIB, calib, 24) < 0) return -1;
    *dig_T1 = (uint16_t)(calib[0] | (calib[1] << 8));
    *dig_T2 = (int16_t)(calib[2] | (calib[3] << 8));
    *dig_T3 = (int16_t)(calib[4] | (calib[5] << 8));
    *dig_P1 = (uint16_t)(calib[6] | (calib[7] << 8));
    *dig_P2 = (int16_t)(calib[8] | (calib[9] << 8));
    *dig_P3 = (int16_t)(calib[10] | (calib[11] << 8));
    *dig_P4 = (int16_t)(calib[12] | (calib[13] << 8));
    *dig_P5 = (int16_t)(calib[14] | (calib[15] << 8));
    *dig_P6 = (int16_t)(calib[16] | (calib[17] << 8));
    *dig_P7 = (int16_t)(calib[18] | (calib[19] << 8));
    *dig_P8 = (int16_t)(calib[20] | (calib[21] << 8));
    *dig_P9 = (int16_t)(calib[22] | (calib[23] << 8));
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID: 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error resetting BMP280: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0xA0) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error writing ctrl_meas register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_read_raw(int fd, int32_t *raw_temp, int32_t *raw_press) {
    uint8_t data[6];
    if (i2c_read_block(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) return -1;
    *raw_press = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    *raw_temp = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);
    return 0;
}

static double bmp280_compensate_temp(int32_t raw_temp, int16_t dig_T1, int16_t dig_T2, int16_t dig_T3, int32_t *t_fine) {
    int32_t var1, var2;
    var1 = ((((raw_temp >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    var2 = (((((raw_temp >> 4) - ((int32_t)dig_T1)) * ((raw_temp >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8;
}

static double bmp280_compensate_press(int32_t raw_press, int16_t dig_P1, int16_t dig_P2, int16_t dig_P3,
                                      int16_t dig_P4, int16_t dig_P5, int16_t dig_P6,
                                      int16_t dig_P7, int16_t dig_P8, int16_t dig_P9, int32_t t_fine) {
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)dig_P6;
    var2 = var2 + ((var1 * (int64_t)dig_P5) << 17);
    var2 = var2 + (((int64_t)dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)dig_P3) >> 8) + ((var1 * (int64_t)dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)dig_P1) >> 33;
    if (var1 == 0) return 0.0;
    p = 1048576 - raw_press;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)dig_P7) << 4);
    return (double)p / 256.0;
}

int main(void) {
    int fd = -1;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "BMP280 initialization failed.\n");
        goto cleanup;
    }

    uint16_t dig_T1;
    int16_t dig_T2, dig_T3, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
    if (bmp280_read_calibration(fd, &dig_T1, &dig_T2, &dig_T3, &dig_P1, &dig_P2, &dig_P3, &dig_P4, &dig_P5, &dig_P6, &dig_P7, &dig_P8, &dig_P9) < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        int32_t raw_temp, raw_press;
        if (bmp280_read_raw(fd, &raw_temp, &raw_press) < 0) {
            fprintf(stderr, "Error reading raw data: %s\n", strerror(errno));
            break;
        }
        int32_t t_fine;
        double temp = bmp280_compensate_temp(raw_temp, dig_T1, dig_T2, dig_T3, &t_fine) / 100.0;
        double press = bmp280_compensate_press(raw_press, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9, t_fine);
        printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temp, press);
        sleep(5);
    }

    ret = 0;

cleanup:
    if (fd >= 0) close(fd);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 4
#define PWM_RANGE 1000
#define PWM_FREQUENCY 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range to %d on GPIO %d.\n", PWM_RANGE, PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency to %d on GPIO %d.\n", PWM_FREQUENCY, PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN, PWM_RANGE / 2) != 0) {
        fprintf(stderr, "Error: failed to set PWM duty cycle on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM on GPIO %d set to %d/%d Hz, duty cycle %d/%d.\n",
           PWM_PIN, PWM_FREQUENCY, PWM_RANGE, PWM_RANGE / 2, PWM_RANGE);

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("PWM stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_5 5
#define GPIO_6 6
#define GPIO_13 13

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line5 = NULL;
static struct gpiod_line *line6 = NULL;
static struct gpiod_line *line13 = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line5) gpiod_line_release(line5);
    if (line6) gpiod_line_release(line6);
    if (line13) gpiod_line_release(line13);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line5 = gpiod_chip_get_line(chip, GPIO_5);
    line6 = gpiod_chip_get_line(chip, GPIO_6);
    line13 = gpiod_chip_get_line(chip, GPIO_13);
    if (!line5 || !line6 || !line13) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(0);
    }

    if (gpiod_line_request_output(line5, "gpio5", 0) < 0 ||
        gpiod_line_request_output(line6, "gpio6", 0) < 0 ||
        gpiod_line_request_output(line13, "gpio13", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(0);
    }

    gpiod_line_set_value(line5, 1);
    gpiod_line_set_value(line6, 1);
    gpiod_line_set_value(line13, 1);

    printf("GPIO 5, 6, 13 set HIGH\n");
    cleanup_and_exit(0);
    return 0;
}

