    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    int ret = snprintf(buffer, buffer_size, "{\"timestamp\": \"%s\", \"sensor_value\": %d}", timestamp, sensor_value);
    if (ret < 0 || (size_t)ret >= buffer_size) {
        fprintf(stderr, "Error formatting data\n");
        return -1;
    }
    return 0;
}

int publish_data(MQTTClient client, const char *topic, const char *payload) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    int rc;

    pubmsg.payload = (void *)payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = MQTT_QOS;
    pubmsg.retained = 0;

    rc = MQTTClient_publishMessage(client, topic, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        return -1;
    }

    rc = MQTTClient_waitForCompletion(client, token, 10000);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to wait for completion, return code %d\n", rc);
        return -1;
    }

    return 0;
}

int main() {
    int sensor_value;
    char data_buffer[256];
    MQTTClient client;
    int rc;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize MQTT client
    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);

    // Connect to MQTT broker
    rc = MQTTClient_connect(client, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_value) == 0) {
            if (format_data(sensor_value, data_buffer, sizeof(data_buffer)) == 0) {
                if (publish_data(client, MQTT_TOPIC, data_buffer) != 0) {
                    fprintf(stderr, "Failed to publish data\n");
                }
            } else {
                fprintf(stderr, "Failed to format data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Sleep for sample interval, checking for termination
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }

    // Cleanup
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

