#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define STEP_DELAY_US 50000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ);

    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);

    signal(SIGINT, signal_handler);

    while (program_running) {
        gpioPWM(PWM_PIN_1, 50);
        gpioPWM(PWM_PIN_2, 50);
