    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line(GPIO_PIN_1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line(GPIO_PIN_2)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    printf("GPIO %d and %d toggled every 0.5 seconds. Press Ctrl+C to exit.\n",
           GPIO_PIN_1, GPIO_PIN_2);

    int state = 0;
    while (running) {
        state = !state;

        if (gpiod_line_set_value(line1, state) < 0) {
            perror("gpiod_line_set_value(line1)");
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, state) < 0) {
            perror("gpiod_line_set_value(line2)");
            goto cleanup;
        }

        printf("GPIO %d = %d, GPIO %d = %d\n",
               GPIO_PIN_1, state, GPIO_PIN_2, state);

        /* Sleep 0.5 seconds, but wake early if interrupted */
        for (int i = 0; i < 5 && running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are low before releasing */
    if (line1) {
        gpiod_line_set_value(line1, 0);
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_set_value(line2, 0);
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting cleanly.\n");
    return ret;
}

