#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B115200
#define READ_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_serial(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_iflag &= ~IGNBRK;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_serial(int fd, unsigned char *buf, size_t len) {
    size_t total = 0;
    while (total < len && running) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("Error reading from serial port");
            return -1;
        }
        if (n == 0) {
            usleep(1000);
            continue;
        }
        total += (size_t)n;
    }
    return (int)total;
}

static int parse_data(const unsigned char *buf, size_t len, float *temperature, float *humidity) {
    if (len < 4) return -1;
    int temp_raw = (buf[0] << 8) | buf[1];
    int hum_raw = (buf[2] << 8) | buf[3];
    *temperature = (float)temp_raw / 10.0f;
    *humidity = (float)hum_raw / 10.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return 1;
    }

    int fd = init_serial(SERIAL_PORT);
    if (fd == -1) {
        return 1;
    }

    unsigned char buffer[1024];
    float temperature, humidity;

    while (running) {
        int bytes_read = read_serial(fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            if (parse_data(buffer, (size_t)bytes_read, &temperature, &humidity) == 0) {
                printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
            } else {
                fprintf(stderr, "Error parsing data\n");
            }
        } else if (bytes_read == -1) {
            fprintf(stderr, "Error reading from serial port\n");
            break;
        }
        usleep(100000);
    }

    if (close(fd) == -1) {
        perror("Error closing serial port");
        return 1;
    }

    return 0;
}

