#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 6
static const unsigned int pins[NUM_PINS] = {4, 17, 22, 23, 24, 27};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_PINS];
static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

int main(void) {
    int ret;
    int i;

    // Set up signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open GPIO chip 0 (Raspberry Pi GPIO controller)
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    // Get and request each GPIO line as output, initially low
    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pins[i]);
            goto cleanup;
        }

        ret = gpiod_line_request_output(lines[i], "gpio-output", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pins[i]);
            goto cleanup;
        }
    }

    // Apply states to each line
    for (i = 0; i < NUM_PINS; i++) {
        ret = gpiod_line_set_value(lines[i], 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO line %u high\n", pins[i]);
            goto cleanup;
        }
        printf("GPIO %u set to HIGH\n", pins[i]);
    }

    // Wait for signal or exit
    while (keep_running) {
        sleep(1);
    }

    // Turn off all lines
    for (i = 0; i < NUM_PINS; i++) {
        gpiod_line_set_value(lines[i], 0);
    }

    // Release lines
    for (i = 0; i < NUM_PINS; i++) {
        gpiod_line_release(lines[i]);
    }

    // Close chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;

cleanup:
    // Release lines that were successfully requested
    for (int j = 0; j < i; j++) {
        gpiod_line_release(lines[j]);
    }
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

