#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CONSUMER    "hcsr04"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("Failed to set trigger low");
        return -1;
    }
    usleep(2);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("Failed to set trigger high");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("Failed to set trigger low");
        return -1;
    }

    /* Wait for echo rising edge (timeout 100 ms) */
    int val;
    for (int i = 0; i < 100000; i++) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("Failed to read echo");
            return -1;
        }
        if (val == 1) break;
        usleep(1);
    }
    if (val != 1) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1;
    }

    /* Measure echo pulse width (timeout 300 ms) */
    long start_tick = 0, end_tick = 0;
    for (int i = 0; i < 300000; i++) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("Failed to read echo");
            return -1;
        }
        if (val == 0) {
            end_tick = i;
            break;
        }
        usleep(1);
    }
    if (end_tick == 0) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1;
    }

    long pulse_width = end_tick - start_tick;
    /* distance = (pulse_width * 34300) / 2 / 1000000 */
    return (pulse_width * 34300) / 2000000;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip 0 (Raspberry Pi) */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    /* Request trigger as output, initial value low */
    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        long distance = measure_distance(trig, echo);
        if (distance < 0) {
            fprintf(stderr, "Measurement failed\n");
        } else {
            printf("Distance: %ld cm\n", distance);
        }
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

