#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    while (program_running) {
        gpioPWM(PWM_PIN_1, 128);
        gpioPWM(PWM_PIN_2, 128);
        gpioPWM(PWM_PIN_3, 128);
        gpioPWM(PWM_PIN_4, 128);
        printf("PWM on GPIO %d, %d, %d, %d: 128\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4);
        sleep(1);

        gpioPWM(PWM_PIN_1, 0);
        gpioPWM(PWM_PIN_2, 0);
        gpioPWM(PWM_PIN_3, 0);
        gpioPWM(PWM_PIN_4, 0);
        printf("PWM on GPIO %d, %d, %d, %d: 0\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4);
        sleep(1);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 4
#define CAPTURE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fh, int request, void *arg) {
    int r;
    do {
        r = ioctl(fh, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    *fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (*fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(*fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Device does not support MJPEG format\n");
        close(*fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(*fd);
        return -1;
    }

    for (i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
            close(*fd);
            return -1;
        }

        void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);
        if (buffer == MAP_FAILED) {
            fprintf(stderr, "mmap failed: %s\n", strerror(errno));
            close(*fd);
            return -1;
        }

        if (xioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            munmap(buffer, buf.length);
            close(*fd);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

static int capture_image(int fd, unsigned char **image_data, size_t *image_size) {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "select failed: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -1;
    }

    *image_data = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (*image_data == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    *image_size = buf.bytesused;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        munmap(*image_data, buf.length);
        return -1;
    }

    return 0;
}

static int save_image(const unsigned char *image_data, size_t image_size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t written = fwrite(image_data, 1, image_size, fp);
    if (written != image_size) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static void cleanup(int fd) {
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
    }
}

int main(void) {
    int fd = -1;
    unsigned char *image_data = NULL;
    size_t image_size = 0;
    int ret = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (init_camera(&fd) != 0) {
        return 1;
    }

    while (running) {
        if (capture_image(fd, &image_data, &image_size) == 0) {
            if (save_image(image_data, image_size, "image.jpg") != 0) {
                ret = 1;
            }
            munmap(image_data, image_size);
        } else {
            ret = 1;
        }
        usleep(CAPTURE_INTERVAL_US);
    }

    cleanup(fd);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (program_running) {
        gpioPWM(PWM_PIN, 50);
        printf("PWM set to 50%%\n");
        fflush(stdout);
        sleep(5);

        if (!program_running) break;

        gpioPWM(PWM_PIN, 0);
        printf("PWM set to 0%%\n");
        fflush(stdout);
        sleep(5);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("Program terminated cleanly\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x27
#define DISPLAY_WIDTH 16

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t value) {
    if (write(fd, &value, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

void display_string(int fd, const char *str) {
    uint8_t buf[DISPLAY_WIDTH + 1];
    int len = strlen(str);
    if (len > DISPLAY_WIDTH) len = DISPLAY_WIDTH;
    memset(buf, 0, sizeof(buf));
    memcpy(buf, str, len);
    i2c_write_byte(fd, buf[0]);
    for (int i = 1; i <= len; i++) {
        i2c_write_byte(fd, buf[i]);
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", PCF8574_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    display_string(i2c_fd, "Hello, World!");
    sleep(1);
    display_string(i2c_fd, "Goodbye!");
    sleep(1);

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 16

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line, "gpio-output", 1) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d set to HIGH\n", GPIO_LINE);
    fflush(stdout);

    cleanup_and_exit(0);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 27

static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Set up signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request line as output, initially low */
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Set line high */
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to HIGH\n", GPIO_LINE);

    /* Wait for signal or exit */
    while (keep_running) {
        sleep(1);
    }

    /* Clean up */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d set to LOW and released\n", GPIO_LINE);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 18
#define PWM_PIN_2 23
#define PWM_PIN_3 24
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define STEP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    int num_pins = sizeof(pins) / sizeof(pins[0]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler.\n");
    }

    int duty = 0;
    int direction = 1;

    while (running) {
        for (int i = 0; i < num_pins; i++) {
            if (gpioPWM(pins[i], duty) != 0) {
                fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }

        printf("PWM duty cycle: %d\n", duty);
        fflush(stdout);

        duty += direction;
        if (duty >= PWM_RANGE) {
            duty = PWM_RANGE;
            direction = -1;
        } else if (duty <= 0) {
            duty = 0;
            direction = 1;
        }

        usleep(STEP_DELAY_US);
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    printf("\nPWM stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CONSUMER    "hcsr04"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trigger low)");
        goto cleanup;
    }
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value(trigger high)");
        goto cleanup;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trigger low)");
        goto cleanup;
    }

    /* Wait for echo rising edge (timeout 30 ms) */
    long long deadline = now_us() + 30000;
    while (gpiod_line_get_value(echo) == 0) {
        if (!running) goto cleanup;
        if (now_us() > deadline) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            goto cleanup;
        }
        usleep(10);
    }
    long long start = now_us();

    /* Wait for echo falling edge (timeout 30 ms) */
    deadline = now_us() + 30000;
    while (gpiod_line_get_value(echo) == 1) {
        if (!running) goto cleanup;
        if (now_us() > deadline) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            goto cleanup;
        }
        usleep(10);
    }
    long long end = now_us();

    long long duration = end - start;
    if (duration < 0) duration = 0;

    /* Speed of sound: 343 m/s = 0.0343 cm/us */
    double distance = (duration * 0.0343) / 2.0;

    printf("Distance: %.2f cm\n", distance);
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 23
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, "gpio23-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to output. Toggling every %d seconds. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET, POLL_INTERVAL_SEC);

    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        val = !val;

        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, val);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    /* Clean up */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

int main() {
    int fd = -1;
    int16_t accel_x, accel_y, accel_z;
    uint8_t buf[6];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) {
            fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
            break;
        }

        accel_x = (int16_t)((buf[0] << 8) | buf[1]);
        accel_y = (int16_t)((buf[2] << 8) | buf[3]);
        accel_z = (int16_t)((buf[4] << 8) | buf[5]);

        printf("Accel X: %d, Y: %d, Z: %d\n", accel_x, accel_y, accel_z);
        usleep(100000);
    }

    if (fd >= 0) {
        close(fd);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define NUM_PINS 3
#define CYCLE_DELAY_SEC 5
#define NUM_CYCLES 3

static const unsigned int pins[NUM_PINS] = {2, 3, 17};

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_output(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static int read_input(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        perror("gpiod_line_get_value");
    }
    return val;
}

static int validate_input(int value) {
    return (value == 0 || value == 1) ? 0 : -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "gpio_output", 0) < 0) {
            perror("gpiod_line_request_output");
            goto cleanup;
        }
    }

    for (int cycle = 0; cycle < NUM_CYCLES && running; cycle++) {
        for (int i = 0; i < NUM_PINS && running; i++) {
            int value = read_input(lines[i]);
            if (value < 0) {
                goto cleanup;
            }
            if (validate_input(value) < 0) {
                fprintf(stderr, "Invalid input on GPIO %u: %d\n", pins[i], value);
                goto cleanup;
            }
            if (set_output(lines[i], value) < 0) {
                goto cleanup;
            }
            printf("GPIO %u: %d\n", pins[i], value);
        }
        if (running) {
            sleep(CYCLE_DELAY_SEC);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

