#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define SHT31_ADDR 0x44
#define I2C_BUS "/dev/i2c-1"
#define MEASURE_CMD 0x2C
#define MEASURE_ARG 0x06
#define POLL_DELAY_MS 10
#define MAX_RETRIES 10

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd, uint8_t arg) {
    uint8_t buf[2] = {cmd, arg};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sht31(int fd, float *temperature, float *humidity) {
    if (i2c_write_cmd(fd, MEASURE_CMD, MEASURE_ARG) < 0) {
        return -1;
    }

    usleep(POLL_DELAY_MS * 1000);

    uint8_t data[6];
    if (i2c_read_bytes(fd, data, 6) < 0) {
        return -1;
    }

    uint16_t t_ticks = (data[0] << 8) | data[1];
    uint16_t h_ticks = (data[3] << 8) | data[4];

    *temperature = -45.0f + (175.0f * (float)t_ticks / 65535.0f);
    *humidity = 100.0f * (float)h_ticks / 65535.0f;

    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Humidity out of range: %.2f%%\n", *humidity);
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SHT31_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("SHT31 sensor reading started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature, humidity;
        if (read_sht31(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        for (int i = 0; i < 50 && running; i++) {
            usleep(100000);
        }
    }

    printf("\nExiting gracefully.\n");
    close(fd);
    return 0;
}

