#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define NUM_PINS 3
#define CYCLES 3

static const unsigned int pins[NUM_PINS] = {2, 3, 17};

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "gpio-output", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < CYCLES && running; i++) {
        int val = i % 2;
        for (int j = 0; j < NUM_PINS; j++) {
            if (gpiod_line_set_value(lines[j], val) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for pin %u\n", pins[j]);
                goto cleanup;
            }
        }
        printf("Cycle %d: GPIO %u=%d, GPIO %u=%d, GPIO %u=%d\n",
               i + 1, pins[0], val, pins[1], val, pins[2], val);
        fflush(stdout);
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

