#include <unistd.h>
#include <gpiod.h>

#define GPIO_18 18
#define GPIO_27 27
#define CONSUMER "gpio-toggle"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line18 = NULL, *line27 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line(GPIO 18)");
        goto cleanup;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line27) {
        perror("gpiod_chip_get_line(GPIO 27)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line18, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(GPIO 18)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line27, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(GPIO 27)");
        goto cleanup;
    }

    printf("GPIO 18 and GPIO 27 toggled every 0.01 seconds. Press Ctrl+C to exit.\n");

    while (running) {
        int val18 = gpiod_line_get_value(line18);
        if (val18 < 0) {
            perror("gpiod_line_get_value(GPIO 18)");
            goto cleanup;
        }

        int val27 = gpiod_line_get_value(line27);
        if (val27 < 0) {
            perror("gpiod_line_get_value(GPIO 27)");
            goto cleanup;
        }

        /* Toggle both lines */
        if (gpiod_line_set_value(line18, !val18) < 0) {
            perror("gpiod_line_set_value(GPIO 18)");
            goto cleanup;
        }

        if (gpiod_line_set_value(line27, !val27) < 0) {
            perror("gpiod_line_set_value(GPIO 27)");
            goto cleanup;
        }

        printf("GPIO 18: %d, GPIO 27: %d\n", val18, val27);
        fflush(stdout);

        usleep(100000); /* 0.01 seconds */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line18) {
        gpiod_line_release(line18);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

