#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define NUM_LEDS 1
#define CYCLE_DELAY_US 5000
#define CYCLE_COUNT 3

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    for (int cycle = 0; cycle < CYCLE_COUNT && program_running; cycle++) {
        gpioWrite(GPIO_PIN, 1);
        gpioDelay(CYCLE_DELAY_US);
        gpioWrite(GPIO_PIN, 0);
        gpioDelay(CYCLE_DELAY_US);
    }

    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

