static int read_temperature(const char *device_path, float *temperature) {
    int fd;
    char buffer[256];
    ssize_t bytes_read;
    char *token;
    long raw_temp;

    fd = open(device_path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device_path, strerror(errno));
        return -1;
    }

    bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", device_path, strerror(errno));
        close(fd);
        return -1;
    }
    buffer[bytes_read] = '\0';

    close(fd);

    token = strstr(buffer, "t=");
    if (token == NULL) {
        fprintf(stderr, "Error: Could not find temperature data in %s\n", device_path);
        return -1;
    }

    raw_temp = strtol(token + 2, NULL, 10);
    *temperature = (float)raw_temp / 1000.0f;

    return 0;
}

static int find_device_path(const char *base_path, const char *device_id, char *device_path, size_t path_size) {
    DIR *dir;
    struct dirent *entry;
    char full_path[512];
    char *filename;

    dir = opendir(base_path);
    if (dir == NULL) {
        fprintf(stderr, "Error opening directory %s: %s\n", base_path, strerror(errno));
        return -1;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        snprintf(full_path, sizeof(full_path), "%s/%s", base_path, entry->d_name);

        if (strstr(full_path, device_id) != NULL) {
            filename = strrchr(full_path, '/');
            if (filename != NULL) {
                filename++;
                snprintf(device_path, path_size, "%s", filename);
                closedir(dir);
                return 0;
            }
        }
    }

    closedir(dir);
    fprintf(stderr, "Error: Could not find device with ID %s in %s\n", device_id, base_path);
    return -1;
}

int main(void) {
    char device_id[32];
    char device_path[256];
    float temperature;
    int i;

    snprintf(device_id, sizeof(device_id), "28-%02x%02x%02x%02x%02x%02x%02x%02x",
             GPIO_PIN, GPIO_PIN, GPIO_PIN, GPIO_PIN, GPIO_PIN, GPIO_PIN, GPIO_PIN, GPIO_PIN);

    if (find_device_path(W1_DEVICE_PATH, device_id, device_path, sizeof(device_path)) != 0) {
        return EXIT_FAILURE;
    }

    snprintf(device_path, sizeof(device_path), "%s/%s/w1_slave", W1_DEVICE_PATH, device_path);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_READINGS && running; i++) {
        if (read_temperature(device_path, &temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Error reading temperature from %s\n", device_path);
            return EXIT_FAILURE;
        }

        if (i < NUM_READINGS - 1 && running) {
            sleep(READ_INTERVAL_SEC);
        }
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_18 18
#define CONSUMER "gpio-toggle"

static volatile sig_atomic_t keep_running = 1;

static void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line(GPIO 17)");
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line(GPIO 18)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line17, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(GPIO 17)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line18, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(GPIO 18)");
        goto cleanup;
    }

    printf("GPIO %d and %d initialized as outputs. Press Ctrl+C to exit.\n",
           GPIO_17, GPIO_18);

    /* Main loop: toggle both lines every second */
    while (keep_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0 || val18 < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        /* Toggle both lines */
        if (gpiod_line_set_value(line17, !val17) < 0) {
            perror("gpiod_line_set_value(GPIO 17)");
            goto cleanup;
        }

        if (gpiod_line_set_value(line18, !val18) < 0) {
            perror("gpiod_line_set_value(GPIO 18)");
            goto cleanup;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n",
               GPIO_17, !val17, GPIO_18, !val18);
        fflush(stdout);

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define ECHO_PIN_ALT 24
#define CONSUMER "hc-sr04"
#define TIMEOUT_US 30000
#define MAX_DISTANCE_CM 400.0
#define MIN_DISTANCE_CM 2.0

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static int wait_for_level(struct gpiod_line *line, int level, long long deadline_us) {
    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            return -1;
        }
        if (val == level) return 0;
        if (now_us() > deadline_us) return -1;
    }
    return -1;
}

static int measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo, float *distance_cm) {
    if (gpiod_line_set_value(trigger, 0) < 0) {
        perror("gpiod_line_set_value (low)");
        return -1;
    }
    usleep(2);

    if (gpiod_line_set_value(trigger, 1) < 0) {
        perror("gpiod_line_set_value (high)");
        return -1;
    }
    usleep(10);

    if (gpiod_line_set_value(trigger, 0) < 0) {
        perror("gpiod_line_set_value (low)");
        return -1;
    }

    long long deadline = now_us() + TIMEOUT_US;
    if (wait_for_level(echo, 1, deadline) < 0) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1;
    }

    long long start = now_us();
    if (wait_for_level(echo, 0, deadline) < 0) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1;
    }
    long long end = now_us();

    long long diff = end - start;
    float distance = (float)diff * 0.0343f / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1;
    }

    *distance_cm = distance;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        perror("gpiod_chip_get_line (trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line (echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance;
        if (measure_distance(trigger, echo, &distance) == 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Measurement failed\n");
        }
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

