#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define NUM_CYCLES 10

static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    // Set up signal handler for clean exit
    signal(SIGINT, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line as output, initially low
    ret = gpiod_line_request_output(line, "gpio_toggle", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to output. Toggling for %d cycles. Press Ctrl+C to exit.\n", GPIO_LINE, NUM_CYCLES);

    // Toggle GPIO state
    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("Failed to read GPIO value");
            break;
        }

        val = !val;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("Failed to set GPIO value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE, val);
        usleep(100000); // 100ms delay
    }

