    signal(SIGTERM, signal_handler);

    while (program_running) {
        int duty_cycle_1 = rand() % (PWM_RANGE + 1);
        int duty_cycle_2 = rand() % (PWM_RANGE + 1);
        int duty_cycle_3 = rand() % (PWM_RANGE + 1);

