#define DHT22_PIN 4
#define MAX_CYCLES 3
#define TIMEOUT_US 1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int level, int timeout_us) {
    int elapsed = 0;
    while (gpiod_line_get_value(line) != level) {
        if (!running) return -1;
        usleep(1);
        elapsed++;
        if (elapsed >= timeout_us) return -1;
    }
    return elapsed;
}

static int read_dht22(struct gpiod_line *line, float *temperature, float *humidity) {
    uint8_t data[5] = {0};
    int i, j;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpiod_line_request_output(line, "dht22", 0) < 0) {
        perror("Failed to request line as output");
        return -1;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set line low");
        gpiod_line_release(line);
        return -1;
    }
    usleep(18000);

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to set line high");
        gpiod_line_release(line);
        return -1;
    }
    usleep(30);

    if (gpiod_line_request_input(line, "dht22") < 0) {
        perror("Failed to request line as input");
        gpiod_line_release(line);
        return -1;
    }

    if (wait_for_level(line, 0, TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for DHT22 response (low)\n");
        gpiod_line_release(line);
        return -1;
    }
    if (wait_for_level(line, 1, TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for DHT22 response (high)\n");
        gpiod_line_release(line);
        return -1;
    }

    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            if (wait_for_level(line, 0, TIMEOUT_US) < 0) {
                fprintf(stderr, "Timeout waiting for bit start\n");
                gpiod_line_release(line);
                return -1;
            }
            int high_time = wait_for_level(line, 1, TIMEOUT_US);
            if (high_time < 0) {
                fprintf(stderr, "Timeout waiting for bit end\n");
                gpiod_line_release(line);
                return -1;
            }
            if (high_time > 40) {
                data[i] |= (1 << (7 - j));
            }
        }
    }

    if (gpiod_line_release(line) < 0) {
        perror("Failed to release line");
        return -1;
    }

    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        fprintf(stderr, "Checksum error: expected 0x%02X, got 0x%02X\n", checksum, data[4]);
        return -1;
    }

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    float temperature, humidity;
    int cycles = 0;

    while (cycles < MAX_CYCLES && running) {
        if (read_dht22(line, &temperature, &humidity) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
            cycles++;
        } else {
            fprintf(stderr, "Failed to read DHT22\n");
        }
        if (cycles < MAX_CYCLES && running) {
            sleep(2);
        }
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

