#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_27 27
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL, *line27 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two GPIO lines */
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line(GPIO 17)");
        goto cleanup;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line27) {
        perror("gpiod_chip_get_line(GPIO 27)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line17, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(GPIO 17)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line27, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(GPIO 27)");
        goto cleanup;
    }

    printf("GPIO 17 and GPIO 27 toggled every 5 seconds. Press Ctrl+C to exit.\n");

    while (running) {
        int val17 = gpiod_line_get_value(line17);
        if (val17 < 0) {
            perror("gpiod_line_get_value(GPIO 17)");
            goto cleanup;
        }

        int val27 = gpiod_line_get_value(line27);
        if (val27 < 0) {
            perror("gpiod_line_get_value(GPIO 27)");
            goto cleanup;
        }

        /* Toggle both lines */
        if (gpiod_line_set_value(line17, !val17) < 0) {
            perror("gpiod_line_set_value(GPIO 17)");
            goto cleanup;
        }

        if (gpiod_line_set_value(line27, !val27) < 0) {
            perror("gpiod_line_set_value(GPIO 27)");
            goto cleanup;
        }

        printf("GPIO 17: %d, GPIO 27: %d\n", !val17, !val27);
        fflush(stdout);

        /* Sleep 5 seconds, checking running flag every second for responsive shutdown */
        for (int i = 0; i < 5 && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are low before releasing */
    if (line17) {
        gpiod_line_set_value(line17, 0);
        gpiod_line_release(line17);
    }
    if (line27) {
        gpiod_line_set_value(line27, 0);
        gpiod_line_release(line27);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nClean shutdown complete.\n");
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PINS {17, 18, 22, 23, 24, 25}
#define NUM_PINS 6
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define STEP_DELAY_US 50000  /* 0.05 seconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int pins[NUM_PINS] = PWM_PINS;
    int i;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM pins */
    for (i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Main loop: cycle through duty cycles 0-255 */
    while (running) {
        for (i = 0; i <= PWM_RANGE && running; i++) {
            for (int j = 0; j < NUM_PINS; j++) {
                if (gpioPWM(pins[j], i) != 0) {
                    fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[j]);
                    gpioTerminate();
                    return EXIT_FAILURE;
                }
            }
            printf("PWM duty cycle: %d\n", i);
            fflush(stdout);
            gpioDelay(STEP_DELAY_US);
        }
    }

    /* Clean shutdown: turn off all PWM outputs */
    for (i = 0; i < NUM_PINS; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

