#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define DHT22_PIN_1 4
#define DHT22_PIN_2 17
#define NUM_READINGS 3
#define READ_INTERVAL 60

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(struct gpiod_line *line, float *temperature, float *humidity) {
    uint8_t data[5] = {0};
    struct timespec ts;
    int val;

    /* Send start signal */
    if (gpiod_line_request_output(line, "dht22", 0) < 0) return -1;
    gpiod_line_set_value(line, 0);
    usleep(18000);
    gpiod_line_set_value(line, 1);
    usleep(30);

    /* Switch to input */
    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    /* Wait for sensor response */
    ts.tv_sec = 0;
    ts.tv_nsec = 10000000; /* 10ms */
    while ((val = gpiod_line_get_value(line)) == 1) {
        nanosleep(&ts, NULL);
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) return -1;
    }
    ts.tv_nsec = 10000000;
    while ((val = gpiod_line_get_value(line)) == 0) {
        nanosleep(&ts, NULL);
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) return -1;
    }
    ts.tv_nsec = 10000000;
    while ((val = gpiod_line_get_value(line)) == 1) {
        nanosleep(&ts, NULL);
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) return -1;
    }

    /* Read 40 bits */
    for (int i = 0; i < 40; i++) {
        ts.tv_nsec = 10000000;
        while ((val = gpiod_line_get_value(line)) == 0) {
            nanosleep(&ts, NULL);
            if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) return -1;
        }
        ts.tv_nsec = 10000000;
        while ((val = gpiod_line_get_value(line)) == 1) {
            nanosleep(&ts, NULL);
            if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) return -1;
        }
        data[i / 8] <<= 1;
        if (ts.tv_nsec > 5000000) {
            data[i / 8] |= 1;
        }
    }

    /* Checksum */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    float temperature, humidity;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, DHT22_PIN_1);
    line2 = gpiod_chip_get_line(chip, DHT22_PIN_2);
    if (!line1 || !line2) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    for (int i = 0; i < NUM_READINGS && running; i++) {
        if (read_dht22(line1, &temperature, &humidity) == 0) {
            printf("Reading %d: Temperature = %.1f C, Humidity = %.1f %%\n", i + 1, temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read DHT22 on GPIO %d\n", DHT22_PIN_1);
        }
        if (read_dht22(line2, &temperature, &humidity) == 0) {
            printf("Reading %d: Temperature = %.1f C, Humidity = %.1f %%\n", i + 1, temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read DHT22 on GPIO %d\n", DHT22_PIN_2);
        }
        if (i < NUM_READINGS - 1 && running) {
            sleep(READ_INTERVAL);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

