#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(const char *device, uint32_t speed, uint8_t bits, uint8_t mode) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode_val = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits_val = bits;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_val) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_max31855(int fd, float *temperature, float *internal_temp) {
    uint8_t tx[4] = {0, 0, 0, 0};
    uint8_t rx[4] = {0, 0, 0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    uint32_t raw = ((uint32_t)rx[0] << 24) | ((uint32_t)rx[1] << 16) |
                   ((uint32_t)rx[2] << 8) | (uint32_t)rx[3];

    if (raw & 0x00010000) {
        fprintf(stderr, "Error: MAX31855 fault detected (raw=0x%08X)\n", raw);
        return -1;
    }

    int16_t temp_val = (int16_t)((raw >> 18) & 0x3FFF);
    if (temp_val & 0x2000) {
        temp_val |= 0xC000;
    }
    *temperature = temp_val * 0.25f;

    int16_t int_val = (int16_t)((raw >> 4) & 0x7FF);
    if (int_val & 0x400) {
        int_val |= 0xF800;
    }
    *internal_temp = int_val * 0.0625f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = spi_init(SPI_DEVICE, SPI_SPEED, SPI_BITS, SPI_MODE);
    if (fd < 0) {
        return 1;
    }

    float temperature, internal_temp;
    if (read_max31855(fd, &temperature, &internal_temp) < 0) {
        close(fd);
        return 1;
    }

    printf("Temperature: %.2f C, Internal Temperature: %.2f C\n", temperature, internal_temp);

    close(fd);
    return 0;
}

