#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define ECHO_PIN2 18
#define ECHO_PIN3 27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long measure_pulse(struct gpiod_line *line) {
    struct timespec ts_start, ts_end;
    long elapsed_ns;

    /* Wait for echo to go high (timeout 100 ms) */
    int val;
    for (int i = 0; i < 100000; i++) {
        val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        if (val == 1) break;
        usleep(1);
    }
    if (val != 1) return -2; /* timeout */

    if (clock_gettime(CLOCK_MONOTONIC, &ts_start) < 0) return -3;

    /* Wait for echo to go low (timeout 30 ms) */
    for (int i = 0; i < 30000; i++) {
        val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        if (val == 0) break;
        usleep(1);
    }
    if (val != 0) return -2; /* timeout */

    if (clock_gettime(CLOCK_MONOTONIC, &ts_end) < 0) return -3;

    elapsed_ns = (ts_end.tv_sec - ts_start.tv_sec) * 1000000000L +
                 (ts_end.tv_nsec - ts_start.tv_nsec);
    return elapsed_ns;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo[3];
    int ret = EXIT_FAILURE;

    /* Open GPIO chip 0 (Raspberry Pi) */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    /* Get trigger line */
    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line (trigger)");
        goto cleanup;
    }

    /* Get echo lines */
    echo[0] = gpiod_chip_get_line(chip, ECHO_PIN);
    echo[1] = gpiod_chip_get_line(chip, ECHO_PIN2);
    echo[2] = gpiod_chip_get_line(chip, ECHO_PIN3);
    if (!echo[0] || !echo[1] || !echo[2]) {
        perror("gpiod_chip_get_line (echo)");
        goto cleanup;
    }

    /* Request trigger as output, initial low */
    if (gpiod_line_request_output(trig, "hc-sr04", 0) < 0) {
        perror("gpiod_line_request_output (trigger)");
        goto cleanup;
    }

    /* Request echo lines as input */
    for (int i = 0; i < 3; i++) {
        if (gpiod_line_request_input(echo[i], "hc-sr04") < 0) {
            perror("gpiod_line_request_input (echo)");
            goto cleanup;
        }
    }

    /* Install signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        goto cleanup;
    }

    printf("HC-SR04 measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Send 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value (trigger high)");
            goto cleanup;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value (trigger low)");
            goto cleanup;
        }

        long dur[3];
        for (int i = 0; i < 3; i++) {
            dur[i] = measure_pulse(echo[i]);
            if (dur[i] < 0) {
                fprintf(stderr, "Error measuring echo on pin %d (code %ld)\n",
                        i == 0 ? ECHO_PIN : (i == 1 ? ECHO_PIN2 : ECHO_PIN3),
                        dur[i]);
                goto cleanup;
            }
        }

        /* Distance = (duration * speed_of_sound) / 2 */
        float dist[3];
        for (int i = 0; i < 3; i++) {
            dist[i] = (float)dur[i] * 0.0343f / 2.0f;
        }

        printf("Distance: %.2f cm, %.2f cm, %.2f cm\n", dist[0], dist[1], dist[2]);
        usleep(500000);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    for (int i = 0; i < 3; i++) {
        if (echo[i]) gpiod_line_release(echo[i]);
    }
    if (chip) gpiod_chip_close(chip);
    return ret;
}

