    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Set the line high */
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to HIGH\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Wait for signal or exit */
    while (keep_running) {
        pause();
    }

    /* Clean up */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d set to LOW and released\n", GPIO_LINE_OFFSET);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define BMP280_ADDR 0x03
#define I2C_BUS "/dev/i2c-1"

#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88

#define BMP280_CHIP_ID 0x58

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID\n");
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(fd, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: Failed to reset BMP280\n");
        return -1;
    }
    usleep(2000);

    uint8_t calib[24];
    if (i2c_read_block(fd, BMP280_REG_CALIB, calib, 24) < 0) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }

    uint16_t dig_T1 = (calib[1] << 8) | calib[0];
    int16_t dig_T2 = (calib[3] << 8) | calib[2];
    int16_t dig_T3 = (calib[5] << 8) | calib[4];
    uint16_t dig_P1 = (calib[7] << 8) | calib[6];
    int16_t dig_P2 = (calib[9] << 8) | calib[8];
    int16_t dig_P3 = (calib[11] << 8) | calib[10];
    int16_t dig_P4 = (calib[13] << 8) | calib[12];
    int16_t dig_P5 = (calib[15] << 8) | calib[14];
    int16_t dig_P6 = (calib[17] << 8) | calib[16];
    int16_t dig_P7 = (calib[19] << 8) | calib[18];
    int16_t dig_P8 = (calib[21] << 8) | calib[20];
    int16_t dig_P9 = (calib[23] << 8) | calib[22];

    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;

    return 0;
}

static int bmp280_read(int fd, float *temp, float *press) {
    uint8_t data[6];
    if (i2c_read_block(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) return -1;

    int32_t raw_press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    uint8_t calib[24];
    if (i2c_read_block(fd, BMP280_REG_CALIB, calib, 24) < 0) return -1;

    uint16_t dig_T1 = (calib[1] << 8) | calib[0];
    int16_t dig_T2 = (calib[3] << 8) | calib[2];
    int16_t dig_T3 = (calib[5] << 8) | calib[4];
    uint16_t dig_P1 = (calib[7] << 8) | calib[6];
    int16_t dig_P2 = (calib[9] << 8) | calib[8];
    int16_t dig_P3 = (calib[11] << 8) | calib[10];
    int16_t dig_P4 = (calib[13] << 8) | calib[12];
    int16_t dig_P5 = (calib[15] << 8) | calib[14];
    int16_t dig_P6 = (calib[17] << 8) | calib[16];
    int16_t dig_P7 = (calib[19] << 8) | calib[18];
    int16_t dig_P8 = (calib[21] << 8) | calib[20];
    int16_t dig_P9 = (calib[23] << 8) | calib[22];

    int32_t var1, var2, t_fine;
    var1 = ((((raw_temp >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    var2 = (((((raw_temp >> 4) - ((int32_t)dig_T1)) * ((raw_temp >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
    t_fine = var1 + var2;
    *temp = (t_fine * 5 + 128) >> 8;
    *temp /= 100.0f;

    int64_t v1, v2, p;
    v1 = ((int64_t)t_fine) - 128000;
    v2 = v1 * v1 * (int64_t)dig_P6;
    v2 = v2 + ((v1 * (int64_t)dig_P5) << 17);
    v2 = v2 + (((int64_t)dig_P4) << 35);
    v1 = ((v1 * v1 * (int64_t)dig_P3) >> 8) + ((v1 * (int64_t)dig_P2) << 12);
    v1 = (((((int64_t)1) << 47) + v1)) * ((int64_t)dig_P1) >> 33;
    if (v1 == 0) return -1;
    p = 1048576 - raw_press;
    p = (((p << 31) - v2) * 3125) / v1;
    v1 = (((int64_t)dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    v2 = (((int64_t)dig_P8) * p) >> 19;
    p = ((p + v1 + v2) >> 8) + (((int64_t)dig_P7) << 4);
    *press = (float)p / 25600.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error: Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("Error: Failed to acquire I2C bus access");
        close(fd);
        return 1;
    }

    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "Error: BMP280 initialization failed\n");
        close(fd);
        return 1;
    }

    int count = 0;
    while (running && count < 3) {
        float temp, press;
        if (bmp280_read(fd, &temp, &press) == 0) {
            printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temp, press);
            count++;
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }
        usleep(1000000);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define NUM_PINS 4

static const unsigned int pins[NUM_PINS] = {17, 22, 23, 24};

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "gpio-output", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for GPIO %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        int val = (i % 2 == 0) ? 1 : 0;
        if (gpiod_line_set_value(lines[i], val) < 0) {
            fprintf(stderr, "gpiod_line_set_value failed for GPIO %u\n", pins[i]);
            goto cleanup;
        }
        printf("GPIO %u set to %d\n", pins[i], val);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

