    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d (BCM) toggled every 1 second. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);
    fflush(stdout);

    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        val = !val;

        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, val);
        fflush(stdout);

        /* Sleep 1 second, but wake early if interrupted */
        for (int i = 0; i < 10 && keep_running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    /* Clean up */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define VEML7700_ADDR 0x10
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS 0x04

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (buf[1] << 8) | buf[0];
    return 0;
}

int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3] = {reg, (value >> 8) & 0xFF, value & 0xFF};
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

int main() {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        goto cleanup;
    }

    // Configure ALS: ALS_IT=100ms, ALS_PERS=1, ALS_GAIN=1x, ALS_EN=1
    if (i2c_write_reg16(fd, VEML7700_ALS_CONF, 0x0003) < 0) {
        perror("Failed to write ALS_CONF");
        goto cleanup;
    }

    while (running) {
        uint16_t als_raw;
        if (i2c_read_reg16(fd, VEML7700_ALS, &als_raw) < 0) {
            perror("Failed to read ALS data");
            goto cleanup;
        }
        printf("ALS: %u\n", als_raw);
        fflush(stdout);
        usleep(500000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B115200
#define READ_INTERVAL_US 100000
#define MAX_RETRIES 10

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

static int init_serial(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_iflag &= ~IGNBRK;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_sensor(int fd, char *buffer, size_t buffer_size) {
    size_t total = 0;
    int retries = 0;

    while (total < buffer_size - 1 && retries < MAX_RETRIES) {
        ssize_t n = read(fd, buffer + total, buffer_size - 1 - total);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                retries++;
                usleep(10000);
                continue;
            }
            fprintf(stderr, "read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            retries++;
            usleep(10000);
            continue;
        }
        total += (size_t)n;
    }

    buffer[total] = '\0';
    return (int)total;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = init_serial(SERIAL_PORT);
    if (fd < 0) {
        return 1;
    }

    char buffer[256];

    while (keep_running) {
        int bytes_read = read_sensor(fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("Sensor data: %s\n", buffer);
            fflush(stdout);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Failed to read sensor data.\n");
            break;
        }
        usleep(READ_INTERVAL_US);
    }

    tcflush(fd, TCIOFLUSH);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define CONSUMER "hcsr04"
#define TIMEOUT_US 30000  /* 30 ms timeout for echo */
#define SOUND_SPEED_CM_S 34300.0

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static int wait_for_level(struct gpiod_line *line, int target, long long deadline_us) {
    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            return -1;
        }
        if (val == target) return 0;
        if (now_us() > deadline_us) return -1;
    }
    return -1;
}

static int measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trigger, 0) < 0) {
        perror("gpiod_line_set_value (low)");
        return -1;
    }
    usleep(2);

    if (gpiod_line_set_value(trigger, 1) < 0) {
        perror("gpiod_line_set_value (high)");
        return -1;
    }
    usleep(10);

    if (gpiod_line_set_value(trigger, 0) < 0) {
        perror("gpiod_line_set_value (low)");
        return -1;
    }

    long long deadline = now_us() + TIMEOUT_US;
    if (wait_for_level(echo, 1, deadline) < 0) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1;
    }

    long long start = now_us();
    deadline = start + TIMEOUT_US;
    if (wait_for_level(echo, 0, deadline) < 0) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1;
    }

    long long end = now_us();
    long long pulse_us = end - start;
    double distance = (pulse_us * SOUND_SPEED_CM_S) / 2000000.0;

    if (distance < 2.0 || distance > 400.0) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1;
    }

    return (int)(distance + 0.5);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        perror("gpiod_chip_get_line (trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line (echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = measure_distance(trigger, echo);
        if (distance >= 0) {
            printf("Distance: %d cm\n", distance);
        } else {
            fprintf(stderr, "Measurement failed\n");
        }
        usleep(500000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

