#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    int fd;
    uint8_t buf[6];
    int16_t x, y, z;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to acquire I2C bus access");
        close(fd);
        return 1;
    }

    // Enable measurement mode
    uint8_t power_ctl = 0x08;
    if (write(fd, &power_ctl, 1) != 1) {
        perror("Failed to write to power control register");
        close(fd);
        return 1;
    }

    // Read 6 bytes of data
    if (read(fd, buf, 6) != 6) {
        perror("Failed to read data from ADXL345");
        close(fd);
        return 1;
    }

    // Combine high and low bytes
    x = (int16_t)((buf[1] << 8) | buf[0]);
    y = (int16_t)((buf[3] << 8) | buf[2]);
    z = (int16_t)((buf[5] << 8) | buf[4]);

    printf("X: %d, Y: %d, Z: %d\n", x, y, z);

    close(fd);
    return 0;
}

