#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQUENCY 1000
#define STEP_DELAY_US 100000  /* 0.1 seconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure PWM pin */
    ret = gpioSetMode(PWM_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %d\n", PWM_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPWMrange(PWM_PIN, PWM_RANGE);
    if (ret != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d: %d\n", PWM_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    if (ret != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d: %d\n", PWM_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main loop: apply PWM and report state */
    while (running) {
        /* Full brightness (1000/1000 duty cycle) */
        ret = gpioPWM(PWM_PIN, PWM_RANGE);
        if (ret != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d: %d\n", PWM_PIN, ret);
            break;
        }
        printf("PWM on GPIO %d: %d/%d\n", PWM_PIN, PWM_RANGE, PWM_RANGE);
        fflush(stdout);

        gpioDelay(STEP_DELAY_US);

        /* Turn off PWM */
        ret = gpioPWM(PWM_PIN, 0);
        if (ret != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d: %d\n", PWM_PIN, ret);
            break;
        }
        printf("PWM on GPIO %d: off\n", PWM_PIN);
        fflush(stdout);

        gpioDelay(STEP_DELAY_US);
    }

    /* Clean shutdown: turn off PWM and terminate pigpio */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nPWM stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

