    int ret = EXIT_FAILURE;

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines for BCM GPIO 4 and 17 */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (GPIO 4)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (GPIO 17)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "gpio-toggle", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 4)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "gpio-toggle", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 17)");
        goto cleanup;
    }

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        goto cleanup;
    }

    printf("Starting %d cycles on GPIO %d and GPIO %d...\n", NUM_CYCLES, GPIO_PIN_1, GPIO_PIN_2);

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        int val1 = i % 2;
        int val2 = (i + 1) % 2;

        if (gpiod_line_set_value(line1, val1) < 0) {
            perror("gpiod_line_set_value (GPIO 4)");
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, val2) < 0) {
            perror("gpiod_line_set_value (GPIO 17)");
            goto cleanup;
        }

        printf("Cycle %d: GPIO %d = %d, GPIO %d = %d\n", i + 1, GPIO_PIN_1, val1, GPIO_PIN_2, val2);
        fflush(stdout);

        /* Sleep 1 second between cycles (interruptible by signals) */
        for (int s = 0; s < 10 && running; s++) {
            usleep(100000); /* 100 ms */
        }
    }

    printf("Completed %d cycles.\n", NUM_CYCLES);
    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are low before releasing */
    if (line1) {
        gpiod_line_set_value(line1, 0);
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_set_value(line2, 0);
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

