#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 22
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define STEP_DELAY_US 10000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);

    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);

    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);

    signal(SIGINT, signal_handler);

    while (program_running) {
        for (int duty_cycle = 0; duty_cycle <= PWM_RANGE && program_running; duty_cycle++) {
            gpioPWM(PWM_PIN_1, duty_cycle);
            gpioPWM(PWM_PIN_2, duty_cycle);
            printf("Duty cycle: %d\n", duty_cycle);
            gpioDelay(STEP_DELAY_US);
        }

        for (int duty_cycle = PWM_RANGE; duty_cycle >= 0 && program_running; duty_cycle--) {
            gpioPWM(PWM_PIN_1, duty_cycle);
            gpioPWM(PWM_PIN_2, duty_cycle);
            printf("Duty cycle: %d\n", duty_cycle);
            gpioDelay(STEP_DELAY_US);
        }
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

