#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LED_PIN 27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL, *echo = NULL, *led = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!trigger || !echo || !led) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output trigger");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04") < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output led");
        goto cleanup;
    }

    gpiod_line_set_value(trigger, 0);
    usleep(2);

    gpiod_line_set_value(trigger, 1);
    usleep(10);
    gpiod_line_set_value(trigger, 0);

    int timeout = 0;
    while (gpiod_line_get_value(echo) == 0) {
        if (++timeout > 100000) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            goto cleanup;
        }
        usleep(1);
    }

    int start_tick = 0;
    timeout = 0;
    while (gpiod_line_get_value(echo) == 1) {
        if (++timeout > 100000) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            goto cleanup;
        }
        usleep(1);
    }
    int end_tick = timeout;

    int distance = (end_tick - start_tick) / 58;

    if (distance < 2 || distance > 400) {
        fprintf(stderr, "Distance out of range: %d cm\n", distance);
        goto cleanup;
    }

    printf("Distance: %d cm\n", distance);

    if (distance < 100) {
        gpiod_line_set_value(led, 1);
    } else {
        gpiod_line_set_value(led, 0);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (led) gpiod_line_release(led);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

