#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_ID 0x12
#define TCS34725_CDATAL 0x14
#define TCS34725_RDATAL 0x16
#define TCS34725_GDATAL 0x18
#define TCS34725_BDATAL 0x1A

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg | TCS34725_COMMAND_BIT, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg | TCS34725_COMMAND_BIT, 1) != 1) {
        fprintf(stderr, "Error setting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[1] << 8 | buf[0];
    return 0;
}

int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read_word(fd, TCS34725_ID, (uint16_t *)&id) < 0) {
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Error: Invalid TCS34725 ID: 0x%02X (expected 0x44)\n", id);
        return -1;
    }
    if (i2c_write_byte(fd, TCS34725_ENABLE, 0x03) < 0) return -1;
    if (i2c_write_byte(fd, TCS34725_ATIME, 0xFF) < 0) return -1;
    return 0;
}

int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (i2c_read_word(fd, TCS34725_CDATAL, clear) < 0) return -1;
    if (i2c_read_word(fd, TCS34725_RDATAL, red) < 0) return -1;
    if (i2c_read_word(fd, TCS34725_GDATAL, green) < 0) return -1;
    if (i2c_read_word(fd, TCS34725_BDATAL, blue) < 0) return -1;
    return 0;
}

int main() {
    int fd;
    uint16_t clear, red, green, blue;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", TCS34725_ADDRESS, strerror(errno));
        close(fd);
        return 1;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "Error initializing TCS34725\n");
        close(fd);
        return 1;
    }

    while (running) {
        if (tcs34725_read_data(fd, &clear, &red, &green, &blue) == 0) {
            printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        usleep(500000);
    }

    i2c_write_byte(fd, TCS34725_ENABLE, 0x00);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_18 18
#define GPIO_23 23
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line18 = NULL;
    struct gpiod_line *line23 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line(GPIO 18)");
        goto cleanup;
    }

    line23 = gpiod_chip_get_line(chip, GPIO_23);
    if (!line23) {
        perror("gpiod_chip_get_line(GPIO 23)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line18, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(GPIO 18)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line23, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(GPIO 23)");
        goto cleanup;
    }

    /* Main loop: toggle both lines every 10 ms */
    while (running) {
        int val18 = gpiod_line_get_value(line18);
        if (val18 < 0) {
            perror("gpiod_line_get_value(GPIO 18)");
            goto cleanup;
        }

        int val23 = gpiod_line_get_value(line23);
        if (val23 < 0) {
            perror("gpiod_line_get_value(GPIO 23)");
            goto cleanup;
        }

        /* Toggle both lines */
        if (gpiod_line_set_value(line18, !val18) < 0) {
            perror("gpiod_line_set_value(GPIO 18)");
            goto cleanup;
        }

        if (gpiod_line_set_value(line23, !val23) < 0) {
            perror("gpiod_line_set_value(GPIO 23)");
            goto cleanup;
        }

        printf("GPIO 18: %d, GPIO 23: %d\n", !val18, !val23);
        fflush(stdout);

        usleep(10000); /* 10 ms */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line18) {
        gpiod_line_release(line18);
    }
    if (line23) {
        gpiod_line_release(line23);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

