#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LOOP_DELAY_US 5000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm_state(int pin, int state) {
    if (gpioPWM(pin, state) != 0) {
        fprintf(stderr, "Error: Failed to set PWM on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        if (set_pwm_state(PWM_PIN_1, 100) != 0 ||
            set_pwm_state(PWM_PIN_2, 50) != 0 ||
            set_pwm_state(PWM_PIN_3, 25) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        printf("PWM state: GPIO %d=100, GPIO %d=50, GPIO %d=25\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);

        if (set_pwm_state(PWM_PIN_1, 0) != 0 ||
            set_pwm_state(PWM_PIN_2, 0) != 0 ||
            set_pwm_state(PWM_PIN_3, 0) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        printf("PWM state: GPIO %d=0, GPIO %d=0, GPIO %d=0\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);

        if (running) {
            gpioDelay(LOOP_DELAY_US);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

