static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_serial(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_sensor(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read < 0) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0;
        }
        fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
        return -1;
    }
    if (bytes_read == 0) {
        return 0;
    }
    buffer[bytes_read] = '\0';
    return (int)bytes_read;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = init_serial(SERIAL_PORT);
    if (fd < 0) {
        return 1;
    }

    char buffer[256];
    while (running) {
        int bytes_read = read_sensor(fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("Sensor Data: %s", buffer);
            fflush(stdout);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading sensor data. Exiting.\n");
            break;
        }
        usleep(READ_INTERVAL_US);
    }

    if (close(fd) != 0) {
        fprintf(stderr, "Error closing serial port: %s\n", strerror(errno));
        return 1;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_3 3
#define GPIO_PIN_5 5

static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line3 = NULL;
    struct gpiod_line *line5 = NULL;
    int ret;

    // Set up signal handler for clean exit
    signal(SIGINT, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO lines
    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!line3) {
        perror("Failed to get GPIO line 3");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line5 = gpiod_chip_get_line(chip, GPIO_PIN_5);
    if (!line5) {
        perror("Failed to get GPIO line 5");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines as outputs, initially low
    ret = gpiod_line_request_output(line3, "gpio3-5-toggle", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line 3 as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line5, "gpio3-5-toggle", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line 5 as output");
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO 3 and 5 toggled. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        // Toggle GPIO 3
        ret = gpiod_line_set_value(line3, 1);
        if (ret < 0) {
            perror("Failed to set GPIO 3 high");
            break;
        }
        printf("GPIO 3 HIGH\n");

        // Toggle GPIO 5
        ret = gpiod_line_set_value(line5, 1);
        if (ret < 0) {
            perror("Failed to set GPIO 5 high");
            break;
        }
        printf("GPIO 5 HIGH\n");

        sleep(1);

        // Toggle GPIO 3
        ret = gpiod_line_set_value(line3, 0);
        if (ret < 0) {
            perror("Failed to set GPIO 3 low");
            break;
        }
        printf("GPIO 3 LOW\n");

        // Toggle GPIO 5
        ret = gpiod_line_set_value(line5, 0);
        if (ret < 0) {
            perror("Failed to set GPIO 5 low");
            break;
        }
        printf("GPIO 5 LOW\n");

        sleep(1);
    }

    // Cleanup
    gpiod_line_release(line3);
    gpiod_line_release(line5);
    gpiod_chip_close(chip);

    printf("\nGPIO lines released. Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN    23
#define LED_PIN     24

#define TIMEOUT_US  30000   /* 30 ms timeout for echo */
#define SOUND_SPEED 0.0343 /* cm/us at 20 C */

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    /* Ensure trigger is low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("Failed to set trigger low");
        return -1;
    }
    usleep(2);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("Failed to set trigger high");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("Failed to set trigger low");
        return -1;
    }

    /* Wait for echo to go high (with timeout) */
    long start_wait = 0;
    while (gpiod_line_get_value(echo) == 0) {
        if (++start_wait > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1;
        }
        usleep(1);
    }

    /* Measure echo pulse width */
    long pulse_width = 0;
    while (gpiod_line_get_value(echo) == 1) {
        if (++pulse_width > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1;
        }
        usleep(1);
    }

    return pulse_width;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *led = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get lines */
    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    led  = gpiod_chip_get_line(chip, LED_PIN);
    if (!trig || !echo || !led) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request lines */
    if (gpiod_line_request_output(trig, "hc-sr04", 0) < 0) {
        perror("gpiod_line_request_output (trigger)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "hc-sr04", 0) < 0) {
        perror("gpiod_line_request_output (led)");
        goto cleanup;
    }

    /* Main loop */
    while (running) {
        long pulse = measure_distance(trig, echo);
        if (pulse < 0) {
            fprintf(stderr, "Measurement failed\n");
            break;
        }

        double distance = (double)pulse * SOUND_SPEED / 2.0;

        if (distance < 20.0) {
            printf("Object detected at %.2f cm\n", distance);
            if (gpiod_line_set_value(led, 1) < 0) {
                perror("Failed to set LED on");
                break;
            }
        } else {
            printf("No object detected\n");
            if (gpiod_line_set_value(led, 0) < 0) {
                perror("Failed to set LED off");
                break;
            }
        }

        usleep(500000); /* 0.5 s between readings */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure LED is off */
    if (led) {
        gpiod_line_set_value(led, 0);
        gpiod_line_release(led);
    }
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define CONSUMER "gpio_output_test"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Set the line high */
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to HIGH\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Wait for signal or 1 second to allow observation */
    for (int i = 0; i < 10 && keep_running; i++) {
        usleep(100000); /* 100 ms */
    }

    /* Set the line low */
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to LOW\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define DELAY_US 200000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (program_running) {
        gpioPWM(PWM_PIN, 50);
        printf("PWM set to 50%%\n");
        gpioDelay(DELAY_US);

        gpioPWM(PWM_PIN, 0);
        printf("PWM set to 0%%\n");
        gpioDelay(DELAY_US);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

